/**
 * The usage notes in Spanish.
 *
 * Keyed by the English note exactly as the card carries it. A note missing
 * from here shows its English, so this file is filled in batches without any
 * card ever going blank — see usageNotes.ts for how it is loaded and why it
 * is not part of the interface tables.
 *
 * Fourteen thousand notes exist. This holds the ones translated so far, and
 * check-usage-notes prints how far along each language is on every build.
 */
export const USE_ES: Record<string, string> = {
  "'abschleppen' — to tow. Colloquially it also means pulling someone in a bar.": "'abschleppen' — remolcar. Coloquialmente también significa ligar con alguien en un bar.",
  "'angesagt sein' — forecast, announced. Also slang for what's currently trendy.": "'angesagt sein' — anunciado, previsto. En argot también: lo que está de moda ahora.",
  "'auf den Cent genau' is the fixed phrase — a virtue in a shop, a friendship-killer at a table. 'abrechnen' is the verb for settling up, and this is the polite way to call off over-precise splitting.": "'auf den Cent genau' es la expresión fija — una virtud en una tienda, un asesino de amistades en la mesa. 'abrechnen' es el verbo para ajustar cuentas, y esta es la manera educada de renunciar a repartir al céntimo.",
  "'auf etwas stehen' — to be into something. Informal, current, and used constantly.": "'auf etwas stehen' — que te vaya algo. Informal, actual y de uso constante.",
  "'Auf etwas stehen' = to be into something. Informal fan talk; works for genres, bands, and people.": "'Auf etwas stehen' = que te vaya algo. Habla informal de fan; sirve para géneros, grupos y personas.",
  "'auf jemanden aufpassen' covers cats, kids and luggage alike. Plain present tense is how favours get asked between friends — no 'könntest du bitte' needed.": "'auf jemanden aufpassen' sirve igual para gatos, niños y equipaje. Los favores entre amigos se piden en presente simple — no hace falta 'könntest du bitte'.",
  "'aufgewacht sein' as conspiracist self-description; comprehension only — hearing this is a warning sign": "'aufgewacht sein' como autodescripción conspiranoica; solo para comprender — oírlo es una señal de alarma",
  "'bedeuten' for meaning. 'Was heißt das?' is the more casual version and just as correct.": "'bedeuten' para el significado. 'Was heißt das?' es la versión más informal e igual de correcta.",
  "'bei jemandem was offen haben' = to have something outstanding with someone — friendly and vague, so you avoid the heavy word 'Schulden'. Works in both directions: 'Du hast noch was bei mir offen.'": "'bei jemandem was offen haben' = tener algo pendiente con alguien — amable y vago, para evitar la palabra pesada 'Schulden'. Funciona en ambos sentidos: 'Du hast noch was bei mir offen.'",
  "'Bei uns' = in my country/family. 'Riesenthema' (giant topic) is casual and vivid — good for explaining your own culture.": "'Bei uns' = en mi país o en mi familia. 'Riesenthema' (tema gigante) es informal y gráfico — ideal para explicar tu propia cultura.",
  "'blank sein' = to have literally nothing left — a notch below 'pleite' and very casual. Friends and family only; never to a colleague or a landlord.": "'blank sein' = no tener literalmente nada — un peldaño por debajo de 'pleite' y muy informal. Solo con amigos y familia; nunca con un compañero ni con el casero.",
  "'borgen' — to lend informally between friends; 'leihen' works too. The dative person comes first: borgst du MIR.": "'borgen' — prestar de forma informal entre amigos; 'leihen' también sirve. La persona en dativo va primero: borgst du MIR.",
  "'Das Match' — loan for a full competitive game; 'ist Schluss' = are we done. Casual.": "'Das Match' — préstamo para un partido completo; 'ist Schluss' = se acabó. Informal.",
  "'davon' avoids repeating the product name after pointing or asking a question about it.": "'davon' evita repetir el nombre del producto después de señalarlo o de preguntar por él.",
  "'davon' refers to an amount of the thing already being discussed and avoids repeating its name.": "'davon' remite a una cantidad de la cosa ya mencionada y evita repetir su nombre.",
  "'der Ansprechpartner / die Ansprechpartnerin' — the person you go to about a thing — is unavoidable in German work life and has no snappy English equivalent. It's also the standard line in every out-of-office reply.": "'der Ansprechpartner / die Ansprechpartnerin' — la persona a la que acudes para un asunto — es inevitable en la vida laboral alemana y no tiene equivalente breve en inglés. Es también la frase estándar de cualquier respuesta automática de ausencia.",
  "'Der Hammer' = the standard casual superlative for events. Informal, all ages under about 50.": "'Der Hammer' = el superlativo informal típico para un evento. Informal, hasta unos 50 años.",
  "'Der Ping' — English loan, no alternative. 'übel' is youth slang for 'terrible'.": "'Der Ping' — préstamo del inglés, sin alternativa. 'übel' es argot juvenil para 'horrible'.",
  "'die Couch' and 'das Sofa' are both everyday words — Couch sounds a shade more casual, Sofa a shade more neutral, and which one you hear depends on the household and the region more than on the setting. Said with mild guilt or open pride depending on the week you've had.": "'die Couch' y 'das Sofa' son dos palabras cotidianas — Couch suena un punto más informal, Sofa un punto más neutro, y cuál oyes depende más de la casa y la región que del contexto. Dicho con algo de culpa o con orgullo abierto, según la semana que hayas tenido.",
  "'die Trotzphase' is the standard, slightly clinical German term for the tantrum years — describing, not complaining, which is why parents say it about their own kids without embarrassment. 'voll' is the casual spoken intensifier.": "'die Trotzphase' es el término alemán estándar, algo clínico, para la etapa de las rabietas — describe, no se queja, y por eso los padres lo dicen de sus propios hijos sin apuro. 'voll' es el intensificador informal del habla.",
  "'dir' means you are choosing it for yourself; 'Such was aus' also works. 'aus' moves to the end. This is the warm, informal way to offer someone a choice.": "'dir' significa que eliges para ti; 'Such was aus' también vale. 'aus' va al final. Es la manera cálida e informal de ofrecerle a alguien elegir.",
  "'doch mal' turns the instruction into a casual suggestion. 'anrufen' splits around the person being called.": "'doch mal' convierte la instrucción en una sugerencia informal. 'anrufen' se separa en torno a la persona a la que llamas.",
  "'doppelt' — double. 'Menge' is a quantity, and colloquially 'a lot'.": "'doppelt' — doble. 'Menge' es una cantidad y, coloquialmente, 'mucho'.",
  "'dran sein' — to be next in turn. Compact, informal and used constantly.": "'dran sein' — ser el siguiente en el turno. Compacto, informal y de uso constante.",
  "'dran' (= daran) is the ultra-casual kitchen way to say 'onto it'; how home cooks actually talk, never written in recipes.": "'dran' (= daran) es la forma ultrainformal de cocina para 'a eso'; así hablan de verdad los cocineros caseros, nunca aparece escrito en las recetas.",
  "'draufschauen' — to look at it. Colloquial and separable.": "'draufschauen' — echarle un vistazo. Coloquial y separable.",
  "'drücken' is the everyday word for hugging — warmer and more casual than 'umarmen'. Also in goodbyes and texts: 'Ich drück dich!' = hugs!": "'drücken' es la palabra cotidiana para abrazar — más cálida e informal que 'umarmen'. También en despedidas y mensajes: 'Ich drück dich!' = ¡un abrazo!",
  "'Du hast einen guten Musikgeschmack' is a real compliment between friends or on a date.": "'Du hast einen guten Musikgeschmack' es un cumplido de verdad entre amigos o en una cita.",
  "'durch sein' — colloquially done for: soaked, worn out, finished.": "'durch sein' — coloquialmente acabado: empapado, gastado, terminado.",
  "'duzen' — to address someone as du. THE sentence for crossing from formal to informal. Traditionally the older person or the senior one offers it.": "'duzen' — tratar a alguien de du. LA frase para pasar del usted al tú. Tradicionalmente la ofrece la persona mayor o de más rango.",
  "'eigentlich' — the casual opener for a serious adult conversation.": "'eigentlich' — la entrada informal a una conversación seria entre adultos.",
  "'ein schlechtes Gewissen haben' = to feel guilty. The second cancellation needs this sentence; the third needs it plus a concrete new date attached, or the friendship quietly cools.": "'ein schlechtes Gewissen haben' = sentirse culpable. La segunda cancelación pide esta frase; la tercera, esta frase más una fecha nueva concreta, o la amistad se enfría en silencio.",
  "'einschlafen' means to fall asleep, but about a habit, a group chat or a friendship it means it quietly died — no decision, no announcement. The gentlest way to admit you stopped going.": "'einschlafen' significa dormirse, pero de una costumbre, un grupo de chat o una amistad quiere decir que se apagó en silencio — sin decisión, sin anuncio. La forma más suave de admitir que dejaste de ir.",
  "'Elfer' is the casual clip everyone uses in speech": "'Elfer' es el recorte informal que todos usan al hablar",
  "'Er ist trocken' is THE standard, respectful phrase for a recovering alcoholic who no longer drinks — not slang, not euphemism.": "'Er ist trocken' es LA expresión estándar y respetuosa para un alcohólico en recuperación que ya no bebe — ni argot ni eufemismo.",
  "'etwas aufrechnen' = to offset one thing against another, and between friends it's an accusation. This is the German way of saying the friendship is worth more than the four euros.": "'etwas aufrechnen' = compensar una cosa con otra, y entre amigos es un reproche. Es la manera alemana de decir que la amistad vale más que los cuatro euros.",
  "'ewig' — eternally, used casually for 'ages'. 'laden' for loading.": "'ewig' — eternamente, en tono informal 'un siglo'. 'laden' para cargar.",
  "'ey' at the end is the all-purpose spoken groan of exasperation — extremely common, extremely casual, never written anywhere official. 'ausgeloggt' beats the technically correct 'abgemeldet' in real speech.": "'ey' al final es el gruñido hablado multiusos de exasperación — extremadamente común, extremadamente informal, nunca escrito en nada oficial. 'ausgeloggt' le gana en el habla real al técnicamente correcto 'abgemeldet'.",
  "'fertig sein' about a person means finished in the sense of nothing left in the tank. Blunt but affectionate between friends and flatmates — say it to your boss and it's simply an insult.": "'fertig sein' de una persona significa que no queda nada en el depósito. Directo pero cariñoso entre amigos y compañeros de piso — dicho a tu jefe es simplemente un insulto.",
  "'fies' is the mean-spirited one — sharper than 'gemein' and very spoken. Between friends it's often half-admiring after a brutal joke; said flat, with no smile, it's completely serious.": "'fies' es la palabra malintencionada — más afilada que 'gemein' y muy hablada. Entre amigos suele sonar medio admirativa tras un chiste brutal; dicha plana, sin sonrisa, va totalmente en serio.",
  "'finden' + person is the safest everyday verdict — claims no friendship, implies no attraction. Spoken German drops the -e ('ich find'). Watch the gap: 'echt nett' is genuine, while bare 'ganz nett' is faint praise.": "'finden' + persona es el veredicto cotidiano más seguro — no afirma amistad ni insinúa atracción. En el habla se cae la -e ('ich find'). Ojo con la diferencia: 'echt nett' es sincero, mientras que 'ganz nett' a secas es un elogio tibio.",
  "'frei Schnauze' — literally free snout: no recipe, pure instinct. Wonderfully casual.": "'frei Schnauze' — literalmente hocico libre: sin receta, puro instinto. Maravillosamente informal.",
  "'für Samstag' — booked for a day. A Transporter needs no lorry licence, which is why friends get asked.": "'für Samstag' — reservado para un día. Un Transporter no exige carné de camión, por eso se recurre a los amigos.",
  "'gar nicht erst' — not even starting. Avoiding the problem entirely.": "'gar nicht erst' — ni siquiera empezar. Evitar el problema por completo.",
  "'geholt werden' = to get collected. Bags out too early get ripped open by crows overnight, and the whole street can then see whose rubbish it was — which is why this comes out slightly urgent rather than casual.": "'geholt werden' = que lo recojan. Las bolsas sacadas demasiado pronto las destrozan los cuervos de noche, y luego toda la calle ve de quién era la basura — por eso esto suena más urgente que informal.",
  "'glatt' — slippery with ice. The winter warning Germans text each other.": "'glatt' — resbaladizo por el hielo. La advertencia de invierno que los alemanes se mandan por mensaje.",
  "'gläubig' — devout. Said plainly, this ends no friendships in Germany.": "'gläubig' — creyente. Dicho sin más, en Alemania no rompe ninguna amistad.",
  "'gucken' is the casual everyday verb (north/central); the south says 'schauen'": "'gucken' es el verbo informal de cada día (norte y centro); el sur dice 'schauen'",
  "'Hä?' — bafflement, rising tone. Rude to teachers, standard between friends. 'Sinn ergeben' — to make sense.": "'Hä?' — desconcierto, tono ascendente. Grosero con un profesor, normal entre amigos. 'Sinn ergeben' — tener sentido.",
  "'halbe-halbe' is common informal German for dividing something into two equal parts.": "'halbe-halbe' es alemán informal habitual para repartir algo en dos partes iguales.",
  "'hinkriegen' — to manage or pull something off. Informal, warm and extremely common.": "'hinkriegen' — apañárselas, conseguir algo. Informal, cálido y muy habitual.",
  "'hinkriegen' is the casual everyday 'to manage, to pull off' — 'schaffen' is a shade more effortful and formal. The tacked-on 'echt' stops it sounding like an automatic pep talk: it means 'I actually believe that.'": "'hinkriegen' es la palabra informal de cada día para apañárselas o conseguirlo — 'schaffen' suena un punto más esforzado y formal. El 'echt' añadido evita que suene a ánimo automático: significa 'de verdad lo creo'.",
  "'Ich meinte damit, dass ...' states the intended meaning directly and avoids an unnecessarily heavy sentence frame.": "'Ich meinte damit, dass ...' expresa el sentido pretendido directamente y evita una estructura de frase innecesariamente pesada.",
  "'in einfach' is colloquial and slightly jokey — asking for simpler words, not slower speech. Germans find it charming from a learner; 'Leichte Sprache' even exists as an official concept.": "'in einfach' es coloquial y algo jocoso — pides palabras más sencillas, no que hablen más despacio. A los alemanes les parece encantador viniendo de quien aprende; 'Leichte Sprache' existe incluso como concepto oficial.",
  "'jeder zahlt seins' — the German default among friends. No awkwardness; it's the system.": "'jeder zahlt seins' — lo normal entre amigos en Alemania. Nada incómodo; es el sistema.",
  "'jemandem etwas abkaufen' = to buy someone's story. Warm rather than confrontational between close friends, because it proves you've been paying attention — but presumptuous to an acquaintance.": "'jemandem etwas abkaufen' = tragarse la historia de alguien. Cálido más que confrontativo entre amigos cercanos, porque demuestra que has estado atento — pero presuntuoso con un conocido.",
  "'jemanden anstecken' = to pass your bug on. 'bloß' in a command is the urgent flavour — said with an arm held out, it's half genuine warning, half joke.": "'jemanden anstecken' = pegarle a alguien tu virus. 'bloß' en una orden aporta el matiz urgente — dicho con el brazo extendido, es medio advertencia sincera, medio broma.",
  "'jemanden unter Druck setzen' is the standard phrase for creating pressure; urgency is a common warning sign.": "'jemanden unter Druck setzen' es la expresión estándar para presionar; la urgencia es una señal de alarma frecuente.",
  "'jemanden vollquatschen' = to talk at someone non-stop. The standard climbdown once the rant runs out of steam. Casual, friends only.": "'jemanden vollquatschen' = hablarle a alguien sin parar. La retirada estándar cuando el discurso se queda sin fuelle. Informal, solo entre amigos.",
  "'jemanden von der Seite anmachen' = to start on someone unprovoked, on the street or on the train. Street-level slang, not office German.": "'jemanden von der Seite anmachen' = meterse con alguien sin motivo, en la calle o en el tren. Argot de calle, no alemán de oficina.",
  "'Jetzt reicht's' is the short version, and the last warning before a row.": "'Jetzt reicht's' es la versión corta, y la última advertencia antes de la bronca.",
  "'Keep your ears stiff' — parting encouragement to someone facing a hard stretch. Warm, informal, and said at doors.": "'Mantén las orejas tiesas' — ánimo de despedida a quien afronta una etapa dura. Cálido, informal, dicho en la puerta.",
  "'kein ... mehr' means there is none left. 'Klopapier' is the ordinary informal word used at home.": "'kein ... mehr' significa que no queda nada. 'Klopapier' es la palabra informal corriente en casa.",
  "'Kein Thema' — not a topic: it doesn't even need discussing. Friendship in two words.": "'Kein Thema' — no es tema: ni hace falta hablarlo. La amistad en dos palabras.",
  "'keinen Nerv für etwas haben' = to have no patience or energy left for something — paperwork, drama, a discussion. Watch the preposition: 'dafür', never 'dazu'. Colloquial and mildly exasperated; extremely common and rarely taught.": "'keinen Nerv für etwas haben' = no tener ya paciencia ni energía para algo — papeleo, dramas, una discusión. Ojo con la preposición: 'dafür', nunca 'dazu'. Coloquial y algo exasperado; muy común y poco enseñado.",
  "'knapp' covers anything in short supply — time, money, a train connection. Here it's the warning shot before you either turn up breathless or cancel.": "'knapp' vale para todo lo que escasea — tiempo, dinero, un enlace de tren. Aquí es el aviso previo antes de llegar sin aliento o cancelar.",
  "'Land unter' comes from coastal flood warnings and means properly overwhelmed. Casual — for colleagues, not for clients.": "'Land unter' viene de los avisos de inundación en la costa y significa desbordado del todo. Informal — para compañeros, no para clientes.",
  "'laufen' is the verb for films showing — 'Der läuft noch' = it's still on. The 'denn ... so' pair turns it into a casual browse instead of a demand.": "'laufen' es el verbo para las películas en cartel — 'Der läuft noch' = todavía la ponen. El par 'denn ... so' lo convierte en un vistazo informal y no en una exigencia.",
  "'lieb' is THE everyday German word for kind-hearted — warmer than 'nett', which can be faint praise ('ganz nett' is nearly an insult). Used about friends, grandmothers, children and helpful strangers alike.": "'lieb' es LA palabra alemana cotidiana para bondadoso — más cálida que 'nett', que puede ser un elogio tibio ('ganz nett' casi insulta). Se usa igual para amigos, abuelas, niños y desconocidos serviciales.",
  "'Lust haben auf + Akkusativ' ('Lust auf Kino?') or 'Lust, etwas zu tun'. This is the neutral everyday version — 'kein Bock' says the same thing in slang and is too casual for your boss or your landlord.": "'Lust haben auf + acusativo' ('Lust auf Kino?') o 'Lust, etwas zu tun'. Esta es la versión neutra de cada día — 'kein Bock' dice lo mismo en argot y es demasiado informal para tu jefe o tu casero.",
  "'mal' makes the command sound casual; use 'in die Ecke' when directing light into it.": "'mal' hace que la orden suene informal; 'in die Ecke' se usa al dirigir la luz hacia allí.",
  "'mal' softens the imperative into a casual request; masculine object is 'deinen Benutzernamen'.": "'mal' convierte el imperativo en una petición informal; el objeto masculino es 'deinen Benutzernamen'.",
  "'mal' turns an offer into something casual. Two seconds, no commitment.": "'mal' convierte el ofrecimiento en algo informal. Dos segundos, sin compromiso.",
  "'Man sieht sich' — literally one sees oneself — is the standard casual sign-off when no date is fixed.": "'Man sieht sich' — literalmente uno se ve — es la despedida informal estándar cuando no hay fecha fijada.",
  "'mitnehmen' is separable; in the informal imperative, 'mit' lands at the end.": "'mitnehmen' es separable; en el imperativo informal, 'mit' va al final.",
  "'neben der Spur sein' — literally 'off the track' — is the everyday idiom for someone distracted, off, not themselves. Affectionate between friends; 'irgendwie' softens it further. Note the sharper cousin 'völlig neben der Spur', which means someone is way off base.": "'neben der Spur sein' — literalmente 'fuera del carril' — es el modismo cotidiano para alguien distraído, desubicado, que no es el mismo. Cariñoso entre amigos; 'irgendwie' lo suaviza aún más. Cuidado con el primo más duro, 'völlig neben der Spur', que significa estar completamente equivocado.",
  "'Nie im Leben' = never in a million years; 'legit' is borrowed straight from English gaming slang. The standard disbelief formula.": "'Nie im Leben' = ni en un millón de años; 'legit' está tomado directamente del argot inglés de los videojuegos. La fórmula estándar de incredulidad.",
  "'nix für ungut' (spoken form of 'nichts für ungut') = no hard feelings, tacked on before or after the blow. Blunt but not hostile — fine with friends; with a boss drop it and use 'Da muss ich widersprechen.'": "'nix für ungut' (forma hablada de 'nichts für ungut') = sin rencor, añadido antes o después del golpe. Directo pero no hostil — vale con amigos; con un jefe déjalo y di 'Da muss ich widersprechen.'",
  "'Pass auf!' is the fastest warning; separable 'aufpassen' becomes 'pass ... auf'.": "'Pass auf!' es la advertencia más rápida; el separable 'aufpassen' se convierte en 'pass ... auf'.",
  "'quatschen' = to chat, casual and affectionate; 'richtig' promises more than this doorstep version. Sometimes genuinely meant, sometimes not — Germans read it roughly the way English speakers read 'we should get coffee'.": "'quatschen' = charlar, informal y cariñoso; 'richtig' promete más que esta versión de puerta. A veces se dice en serio, a veces no — los alemanes lo leen más o menos como los angloparlantes leen 'we should get coffee'.",
  "'rauf und runter' = over and over — how Germans confess an obsession with a song or a show ('Die Serie hab ich rauf und runter geguckt'). Casual, affectionate, no negative edge at all.": "'rauf und runter' = una y otra vez — así confiesan los alemanes una obsesión con una canción o una serie ('Die Serie hab ich rauf und runter geguckt'). Informal, cariñoso, sin ningún matiz negativo.",
  "'rausfliegen' — from the fuse pack, here about a back. Colloquial and instantly understood.": "'rausfliegen' — del paquete de los fusibles, aquí sobre una espalda. Coloquial y se entiende al instante.",
  "'rumhängen' (from 'herumhängen') = to hang about doing nothing. Casual and slightly teenage — perfect between friends and partners, odd in front of your boss.": "'rumhängen' (de 'herumhängen') = estar por ahí sin hacer nada. Informal y algo adolescente — perfecto entre amigos y pareja, raro delante de tu jefe.",
  "'Sag bloß!' is delighted disbelief, not a real request to speak. The mock reproach after it is a compliment in disguise: it says the news was too good not to have reached you sooner. Friends and family only — to a colleague it sounds nosy.": "'Sag bloß!' es incredulidad encantada, no una petición real de que hablen. El reproche fingido que sigue es un cumplido disfrazado: dice que la noticia era demasiado buena para no haberte llegado antes. Solo amigos y familia — a un compañero le suena entrometido.",
  "'schauen' or 'gucken' — gucken is more casual. No preposition before the platform.": "'schauen' o 'gucken' — gucken es más informal. Sin preposición delante de la plataforma.",
  "'schlapp' (colloquial) = run-down, drained; 'kaum' = barely.": "'schlapp' (coloquial) = decaído, agotado; 'kaum' = apenas.",
  "'schwurbeln' is the current word for conspiracy-rambling; informal, everywhere since the pandemic": "'schwurbeln' es la palabra actual para el desvarío conspiranoico; informal, en todas partes desde la pandemia",
  "'sich anfühlen' is used for the experience ('Wie hat sich das angefühlt?'), 'sich fühlen' for the person ('Wie fühlst du dich?'). Warm and a little earnest — save it for friends, not for the colleague telling you about their commute.": "'sich anfühlen' se usa para la experiencia ('Wie hat sich das angefühlt?'), 'sich fühlen' para la persona ('Wie fühlst du dich?'). Cálido y algo serio — guárdalo para los amigos, no para el compañero que te cuenta su trayecto.",
  "'sich aufs Ohr hauen' — literally to throw yourself onto your ear. Casual and a bit blokey, for friends and flatmates; 'ein Nickerchen machen' is the neutral way to describe the same twenty minutes.": "'sich aufs Ohr hauen' — literalmente tirarse sobre la oreja. Informal y algo de colegas, para amigos y compañeros de piso; 'ein Nickerchen machen' describe los mismos veinte minutos en tono neutro.",
  "'Sich ein Haustier anschaffen' = to get a pet. Affectionate casual slang: 'das Fellbaby' (fur baby).": "'Sich ein Haustier anschaffen' = tener una mascota. Argot cariñoso e informal: 'das Fellbaby' (bebé peludo).",
  "'sich etwas kaputt machen' = to wreck a body part — casual, slightly dramatic, used for backs and knees above all. 'Unkraut jäten' = to weed.": "'sich etwas kaputt machen' = destrozarse una parte del cuerpo — informal, algo dramático, sobre todo para espaldas y rodillas. 'Unkraut jäten' = quitar malas hierbas.",
  "'Sich etwas ziehen' = to download, distinctly casual register; the standard buddy advice before a risky purchase.": "'Sich etwas ziehen' = descargar, registro claramente informal; el consejo de colega estándar antes de una compra arriesgada.",
  "'sich etwas ziehen' is slang for downloading; more neutral: 'runterladen' or the loan verb 'downloaden' — all three are common.": "'sich etwas ziehen' es argot para descargar; más neutro: 'runterladen' o el verbo prestado 'downloaden' — los tres son habituales.",
  "'sich irren' — the dignified admission, equally at home in a meeting and in the kitchen. Blunter and more colloquial: 'Ich lag komplett falsch.' Never 'Ich war falsch' — that isn't German.": "'sich irren' — la admisión digna, igual de propia en una reunión que en la cocina. Más directo y coloquial: 'Ich lag komplett falsch.' Nunca 'Ich war falsch' — eso no es alemán.",
  "'sich reinsteigern' = to spiral into something; informal, the natural way to describe the rabbit-hole process": "'sich reinsteigern' = obsesionarse cada vez más con algo; informal, la forma natural de describir la espiral",
  "'sicherheitshalber' explains that you are checking to avoid an unnecessary mistake.": "'sicherheitshalber' explica que compruebas algo para evitar un error innecesario.",
  "'spinnen' — literally to spin — is the everyday verb for being crazy. Between friends it is affectionate; at a stranger it is an insult.": "'spinnen' — literalmente hilar — es el verbo cotidiano para estar loco. Entre amigos es cariñoso; a un desconocido es un insulto.",
  "'sportlich' — sporty, and also 'smart-casual' about clothes. Both are common.": "'sportlich' — deportivo, y también 'smart casual' con la ropa. Ambos usos son habituales.",
  "'Strafzettel' — penalty slip. Also 'Knöllchen' colloquially, which sounds far too sweet for what it is.": "'Strafzettel' — la multa en papel. Coloquialmente también 'Knöllchen', que suena demasiado dulce para lo que es.",
  "'total' as an intensifier is thoroughly spoken German and slightly informal.": "'total' como intensificador es alemán hablado puro y algo informal.",
  "'unbedingt' + colloquial 'was' (for etwas) = maximum urgency, zero formality. Best-friend register; the standard wind-up before gossip.": "'unbedingt' + el coloquial 'was' (por etwas) = urgencia máxima, formalidad cero. Registro de mejores amigos; la carrerilla estándar antes del cotilleo.",
  "'unterschiedlich' — differing. Germans use it constantly to avoid overgeneralising.": "'unterschiedlich' — dispar, variable. Los alemanes lo usan sin parar para no generalizar.",
  "'Voll der/die X' is casual youth-speak amplification; pure banter register among friends and in voice chat.": "'Voll der/die X' es una amplificación informal del habla juvenil; puro registro de broma entre amigos y en el chat de voz.",
  "'voll' is THE everyday intensifier under about 40 — voll gut, voll nervig, voll teuer. Casual but harmless; drop it for the grown-up version: 'Das ist ziemlich langweilig.'": "'voll' es EL intensificador cotidiano por debajo de los 40 — voll gut, voll nervig, voll teuer. Informal pero inofensivo; para la versión adulta se quita: 'Das ist ziemlich langweilig.'",
  "'von deinem' = from yours, dative with the noun simply dropped. Forks crossing the table are completely normal between friends, couples and family; with people you've just met, ask first rather than reach.": "'von deinem' = del tuyo, dativo con el sustantivo simplemente omitido. Los tenedores que cruzan la mesa son de lo más normal entre amigos, parejas y familia; con gente que acabas de conocer, pregunta antes de alargar el brazo.",
  "'was trinken gehen' — the standard invitation. Casual, open-ended, no commitment implied.": "'was trinken gehen' — la invitación estándar. Informal, abierta, sin compromiso.",
  "'wegmachen' colloquially for putting something aside. 'mal' softens the announcement.": "'wegmachen' coloquialmente para apartar algo. 'mal' suaviza el aviso.",
  "'Wie hoch' for amounts of money. A completely normal question between German friends.": "'Wie hoch' para cantidades de dinero. Una pregunta de lo más normal entre amigos alemanes.",
  "'wieder drauf haben' — colloquial and compact. Bike chains come off constantly.": "'wieder drauf haben' — coloquial y compacto. Las cadenas de bici se salen constantemente.",
  "'Wofür' is the normal neutral form; 'für was' is regional or very casual.": "'Wofür' es la forma neutra normal; 'für was' es regional o muy informal.",
  "'Zeit mitbringen' — the honest warning. Open hours mean open-ended waiting.": "'Zeit mitbringen' — la advertencia honesta. Horario sin cita significa espera sin final.",
  "'zurückrufen' is separable: ich rufe dich zurück. 'mitten in was' (= in etwas) is casual spoken German; at work the same excuse is 'Ich bin gerade in einem Termin.'": "'zurückrufen' es separable: ich rufe dich zurück. 'mitten in was' (= in etwas) es alemán hablado informal; en el trabajo la misma excusa es 'Ich bin gerade in einem Termin.'",
  "'Zuschlagen' = to strike when a deal appears — THE verb for sale purchases, gaming or otherwise. Casual bragging register.": "'Zuschlagen' = lanzarse cuando aparece una oferta — EL verbo de las compras en rebajas, en gaming o donde sea. Registro informal de fanfarronería.",
  "'zwischen den Jahren' is the fixed expression for the dead week between Christmas and New Year, when half the country is away and nothing gets decided. Standard November small talk; 'eigentlich' keeps it casual rather than nosy.": "'zwischen den Jahren' es la expresión fija para la semana muerta entre Navidad y Año Nuevo, cuando medio país está fuera y no se decide nada. Charla estándar de noviembre; 'eigentlich' la mantiene informal y no entrometida.",
  "\"Kiste\" is a crate or box, and colloquially any old thing. Say this before you sign for anything that looks tampered with.": "'Kiste' es una caja o un cajón, y coloquialmente cualquier cosa. Di esto antes de firmar algo que parezca manipulado.",
  "18+ conversational — the standard casual way to ask about turn-ons ('stehen auf + Akk'). Between partners or in open flirting, never at work.": "Conversación para adultos — la manera informal estándar de preguntar qué le pone a alguien ('stehen auf + acusativo'). Entre parejas o en un flirteo abierto, nunca en el trabajo.",
  "A broad casual check-in about life, work or whatever is currently going on. The situation decides how wide the answer should be.": "Una pregunta amplia e informal sobre la vida, el trabajo o lo que esté pasando ahora. La situación decide cuán amplia debe ser la respuesta.",
  "A broad casual question about someone's work, studies or life. It usually asks more than what they are doing this exact second.": "Una pregunta amplia e informal sobre el trabajo, los estudios o la vida de alguien. Normalmente pregunta más que lo que está haciendo en este segundo.",
  "A broad catch-up question about someone's current life. 'zurzeit' means these days or at present, and 'so' keeps the question casual.": "Una pregunta amplia para ponerse al día sobre la vida actual. 'zurzeit' significa actualmente, y 'so' mantiene la pregunta informal.",
  "A casual event or venue question. 'mit wem' asks which person or group someone came with or is spending time with.": "Una pregunta informal en un evento o local. 'mit wem' pregunta con qué persona o grupo ha venido alguien o está pasando el rato.",
  "A casual first-meeting question about whether someone comes from the local area. It is less broad than asking which country or city they come from.": "Una pregunta informal en un primer encuentro sobre si alguien es de la zona. Es más acotada que preguntar de qué país o ciudad viene.",
  "A casual purpose question when someone has an object, tool, file or unusual plan.": "Una pregunta informal por la finalidad, cuando alguien tiene un objeto, una herramienta, un archivo o un plan poco habitual.",
  "A casual question about an object when you do not know or do not need its exact name. 'Ding' is everyday but vague.": "Una pregunta informal sobre un objeto cuando no sabes o no necesitas su nombre exacto. 'Ding' es cotidiano pero vago.",
  "A colloquial fixed expression. It is not sexual in this use.": "Una expresión fija coloquial. En este uso no tiene sentido sexual.",
  "A common getting-to-know-you question when either work or study could fit. Avoid it if the setting makes the answer obvious.": "Una pregunta habitual para conocerse cuando podrían encajar tanto el trabajo como los estudios. Evítala si el contexto ya deja clara la respuesta.",
  "A common informal reassurance. It literally mentions your head, but the meaning is not to worry.": "Una frase de tranquilidad informal muy común. Literalmente menciona tu cabeza, pero significa: no te preocupes.",
  "A common informal response to disappointing news or an annoying problem.": "Una respuesta informal habitual ante una noticia decepcionante o un problema molesto.",
  "A common shortened suggestion to avoid deciding too early. A complete version is 'Warten wir erst mal ab'.": "Una sugerencia abreviada habitual para no decidir demasiado pronto. La versión completa es 'Warten wir erst mal ab'.",
  "A common use of sammeln among friends, at work or in a family.": "Un uso habitual de sammeln entre amigos, en el trabajo o en familia.",
  "A considerate response to bad news when a casual reaction would feel too light.": "Una respuesta considerada ante malas noticias, cuando una reacción informal sonaría demasiado ligera.",
  "A direct informal question about ability. English keeps the main verb in its plain form after 'can': 'Can you do...?', never 'Can you to do...?'.": "Una pregunta informal y directa sobre la capacidad. En inglés el verbo principal se mantiene en su forma simple tras 'can': 'Can you do...?', nunca 'Can you to do...?'.",
  "A direct warning that a condition or necessary step cannot be skipped.": "Una advertencia directa: no se puede saltar una condición o un paso necesario.",
  "A kind boundary always names a new time — postponing without one is heard as a refusal. 'Ich schaff's nicht mehr' says you're out of capacity, not out of interest, which is the difference that keeps the friendship intact.": "Un límite amable siempre nombra una fecha nueva — posponer sin ella se oye como una negativa. 'Ich schaff's nicht mehr' dice que se te acabó la capacidad, no el interés, y esa diferencia es la que mantiene intacta la amistad.",
  "A later colloquial shortcut for when the restaurant context is already obvious. 'was' is spoken 'etwas' and can imply a table or some space, but it is less clear than 'Haben Sie noch einen Tisch frei?' — learn the explicit version first.": "Un atajo coloquial posterior, cuando el contexto del restaurante ya es obvio. 'was' es el 'etwas' hablado y puede referirse a una mesa o a algo de sitio, pero es menos claro que 'Haben Sie noch einen Tisch frei?' — aprende primero la versión explícita.",
  "A natural follow-up after meeting two friends. 'seid ihr' addresses both people together.": "Una continuación natural al encontrarte con dos amigos. 'seid ihr' se dirige a los dos a la vez.",
  "A natural urgent warning. German can use this short phrase without a verb when the danger is obvious.": "Una advertencia urgente natural. El alemán puede prescindir del verbo cuando el peligro es evidente.",
  "A natural warning to an animal gulping food. The situation supplies the missing verb, so German keeps it short.": "Una advertencia natural a un animal que engulle la comida. La situación aporta el verbo que falta, así que el alemán se queda corto.",
  "A normal informal request for a very short wait. Add 'bitte' when you want it to sound softer.": "Una petición informal normal para una espera muy breve. Añade 'bitte' si la quieres más suave.",
  "A practical check that helps the group avoid stopping again once the task has begun.": "Una comprobación práctica que evita al grupo tener que parar otra vez una vez empezado.",
  "A safety warning in frost, snow or freezing rain. 'glatt' does not always mean icy, so slippery is the broad translation.": "Una advertencia de seguridad con helada, nieve o lluvia engelante. 'glatt' no siempre significa helado, por eso la traducción amplia es resbaladizo.",
  "A serious accusation, not casual criticism.": "Una acusación grave, no una crítica pasajera.",
  "A shade more emotional than 'keine Lust' — this is about your state, not the activity. Warning: between partners at night it means exactly what it means in English.": "Un punto más emocional que 'keine Lust' — aquí se habla de tu estado, no de la actividad. Aviso: entre pareja, de noche, significa exactamente lo que significa en inglés.",
  "A short warning after treatment or when a pet worries a sore spot. The object is obvious, so German leaves it out.": "Una advertencia breve tras un tratamiento o cuando una mascota se hurga una herida. El objeto es evidente, así que el alemán lo omite.",
  "A shortened vulgar dismissal. It can be joking only between very close friends with the right tone; otherwise it is an insult.": "Un rechazo vulgar abreviado. Solo pasa como broma entre amigos muy cercanos con el tono adecuado; en otro caso es un insulto.",
  "A standard informal request. The favour itself normally follows immediately.": "Una petición informal estándar. El favor en sí suele venir justo después.",
  "A standard Monday small-talk question with friends, classmates and colleagues you know.": "La típica pregunta de charla del lunes con amigos, compañeros de clase y colegas conocidos.",
  "A standing offer between partners or close friends; warm, no drama.": "Un ofrecimiento que siempre está en pie, entre pareja o amigos cercanos; cálido, sin dramas.",
  "A very common casual follow-up when the first topic is finished and you want the conversation to continue.": "Una continuación informal muy común cuando el primer tema se agota y quieres que siga la conversación.",
  "A very common informal way to check whether a day suits someone.": "Una forma informal muy común de preguntar si un día le viene bien a alguien.",
  "abgefahren — driven off, worn. Also slang for 'amazing'; the tyre meaning is older.": "abgefahren — gastado, desgastado. En argot también 'alucinante'; el sentido del neumático es más antiguo.",
  "Achtung! is the warning word; die Ampel = the traffic light, always feminine.": "Achtung! es la palabra de advertencia; die Ampel = el semáforo, siempre femenino.",
  "Affectionate or dry, harmless — literally 'fun bird'. Said fondly, or deadpan when the joke was bad. Safe with anyone informal.": "Cariñoso o seco, inofensivo — literalmente 'pájaro divertido'. Dicho con afecto, o con cara de póker cuando el chiste era malo. Seguro con cualquiera en registro informal.",
  "Affectionate teasing, harmless — partner, kids, close friends. Almost never stings; it implies fond exasperation, not stupidity.": "Broma cariñosa, inofensiva — pareja, hijos, amigos cercanos. Casi nunca escuece; implica exasperación afectuosa, no estupidez.",
  "Affectionate, harmless — for someone talking nonsense or clowning around. Partner, friends, kids. Warm, never a real insult.": "Cariñoso, inofensivo — para alguien que dice tonterías o hace el payaso. Pareja, amigos, niños. Cálido, nunca un insulto de verdad.",
  "Afterwards": "Después",
  "Agreeing": "Estar de acuerdo",
  "Allotment neighbours — advisors, rivals and friends across one fence. Mostly all three.": "Vecinos de huerto urbano — asesores, rivales y amigos a un lado y otro de la valla. Casi siempre las tres cosas.",
  "Almost always plural; singular das Beziehungsproblem. Neutral, the word you use confiding in friends.": "Casi siempre en plural; singular das Beziehungsproblem. Neutro, la palabra que usas al confiarte a los amigos.",
  "also colloquially \"incredibly\": unwahrscheinlich gut": "coloquialmente también 'increíblemente': unwahrscheinlich gut",
  "also colloquially \"massively\": tierisch gut": "coloquialmente también 'un montón': tierisch gut",
  "always plural": "siempre en plural",
  "Among friends, immediately after the news. 'Mal' softens it into eager excitement, not a command.": "Entre amigos, justo después de la noticia. 'Mal' lo convierte en entusiasmo impaciente, no en una orden.",
  "An informal reaction to a plan failing, something breaking or another everyday setback.": "Una reacción informal cuando un plan falla, algo se rompe o surge otro contratiempo cotidiano.",
  "Anglicism, under-40 casual; scrollen is fully naturalized for everyone, doomscrollen still youth-flavoured": "Anglicismo, informal entre menores de 40; scrollen está plenamente naturalizado para todos, doomscrollen todavía suena juvenil",
  "ANGRY — the final rung before consequences, and everyone hears it that way. Adults use it on each other too, where it lands as a real threat rather than a warning.": "ENFADADO — el último peldaño antes de las consecuencias, y así lo oye todo el mundo. Los adultos también se lo dicen entre sí, donde suena a amenaza real más que a advertencia.",
  "Ask two or more people for the story of how they first met. It can be about friends, a couple or colleagues.": "Pregunta a dos o más personas la historia de cómo se conocieron. Puede ser sobre amigos, una pareja o colegas.",
  "Asking for the bill": "Pedir la cuenta",
  "At the table, informal. One guest: 'Greif zu!' Signals the eating may begin.": "En la mesa, informal. Con un invitado: 'Greif zu!' Señala que ya se puede empezar a comer.",
  "At the till": "En la caja",
  "aufblasen — inflating. 'Hilf mir mal' — the casual recruiting of bystanders.": "aufblasen — inflar. 'Hilf mir mal' — la manera informal de reclutar a quien esté cerca.",
  "aufdrängen — pressing something on someone. The warning before every market stroll.": "aufdrängen — endilgarle algo a alguien. La advertencia antes de cada paseo por el mercado.",
  "aufziehen — a storm pulling up. denn delivers the warning in plain word order.": "aufziehen — una tormenta que se acerca. denn da la advertencia con el orden de palabras más simple.",
  "Aus der Kirche austreten = to formally leave the church. Casually, mal austreten = to nip to the loo.": "Aus der Kirche austreten = darse de baja oficialmente de la Iglesia. En tono informal, mal austreten = ir un momento al baño.",
  "auslaufen — leaking out. 'hinüber sein' — colloquially beyond saving.": "auslaufen — salirse, gotear. 'hinüber sein' — coloquialmente, irrecuperable.",
  "ausstrecken splits in the imperative; mal softens the order to a casual prompt. German uses die, not 'your', with body parts.": "ausstrecken se separa en imperativo; mal suaviza la orden hasta convertirla en una invitación informal. Con las partes del cuerpo el alemán usa die, no 'tu'.",
  "Banter": "Bromas",
  "beim Umzug = with the move. Moving house with friends (and pizza afterwards) is completely standard in Germany.": "beim Umzug = en la mudanza. Mudarse con amigos (y pizza después) es de lo más normal en Alemania.",
  "beraten — advising. 'einen' — the colloquial accusative of man.": "beraten — asesorar. 'einen' — el acusativo coloquial de man.",
  "Between friends: Kannst du mir zehn Euro borgen? Standard German prefers leihen.": "Entre amigos: Kannst du mir zehn Euro borgen? El alemán estándar prefiere leihen.",
  "Blunt but completely normal between partners and friends — German directness in action": "Directo pero de lo más normal entre pareja y amigos — la franqueza alemana en acción",
  "Blunt but standard dismissal of a politician. Strong opinion, casual delivery — fine between partners and friends. '...von ihr' for her.": "Directo pero estándar como rechazo a un político. Opinión fuerte, tono informal — vale entre pareja y amigos. '...von ihr' para ella.",
  "Blunt insult, literally a full fencepost. Friends-only register.": "Insulto directo, literalmente un poste de valla entero. Solo entre amigos.",
  "Blunt self-criticism that admits your behaviour was bad. It can sound sincere among friends, but use a cleaner apology at work.": "Autocrítica directa que admite que tu comportamiento estuvo mal. Entre amigos puede sonar sincera, pero en el trabajo usa una disculpa más limpia.",
  "borgen — the casual borrow-lend verb. die Leiter migrates between households like a shared pet.": "borgen — el verbo informal de prestar y pedir prestado. die Leiter migra de casa en casa como una mascota compartida.",
  "Both a literal on-set announcement and a warning that everything from now on is Content; läuft = runs, the standard verb for recording devices.": "A la vez el aviso literal en el set y la advertencia de que a partir de ahora todo es Content; läuft = está en marcha, el verbo estándar para los aparatos de grabación.",
  "Both forms are normal. 'Sinn ergeben' is the standard, register-neutral form; 'Sinn machen' is very common in everyday speech and informal writing. Negative: 'Das ergibt keinen Sinn' or conversational 'Das macht keinen Sinn'.": "Ambas formas son normales. 'Sinn ergeben' es la forma estándar, neutra de registro; 'Sinn machen' es muy común en el habla cotidiana y la escritura informal. En negativo: 'Das ergibt keinen Sinn' o, en conversación, 'Das macht keinen Sinn'.",
  "bumming a cigarette; casual, smoker-to-smoker only": "gorronear un cigarrillo; informal, solo de fumador a fumador",
  "Buying time": "Ganar tiempo",
  "Careful — between two people who might be dating, this IS the small confession, one step below 'Ich hab dich lieb'. Between friends it's plain and warm. Tone and timing carry the whole meaning.": "Cuidado — entre dos personas que quizá estén saliendo, ESTA es la pequeña confesión, un peldaño por debajo de 'Ich hab dich lieb'. Entre amigos es sencilla y cálida. El tono y el momento cargan con todo el sentido.",
  "Casual": "Informal",
  "Casual — and ambiguous by design: 'zocken' means both gambling and video gaming. Among under-40s the default reading is gaming; in a casino context it's gambling.": "Informal — y ambiguo a propósito: 'zocken' significa tanto apostar como jugar a videojuegos. Entre menores de 40 la lectura por defecto es el videojuego; en un casino es el juego de azar.",
  "Casual — Ding literally means 'thing'": "Informal — Ding significa literalmente 'cosa'",
  "Casual — literally 'now we have the salad'": "Informal — literalmente 'ahora tenemos la ensalada'",
  "Casual — literally 'that's not my beer'": "Informal — literalmente 'esa no es mi cerveza'",
  "Casual — literally 'you had pig'": "Informal — literalmente 'tuviste cerdo'",
  "Casual agreement": "Acuerdo informal",
  "Casual and dramatic; often frustration rather than literal loss of control.": "Informal y dramático; suele ser frustración más que una pérdida real de control.",
  "casual between friends; the English loans (Foundation, Concealer) are standard in German — French keeps 'fond de teint'": "informal entre amigos; los préstamos ingleses (Foundation, Concealer) son lo estándar en alemán — el francés conserva 'fond de teint'",
  "Casual check-in mid-explanation.": "Comprobación informal a mitad de una explicación.",
  "casual clipping of 'Prominenter' — everyday word": "recorte informal de 'Prominenter' — palabra de uso diario",
  "Casual complaint, one hour in. Someone packed too much Brotzeit.": "Queja informal tras una hora. Alguien metió demasiada Brotzeit.",
  "casual compliment; stehen + dative = to suit someone": "cumplido informal; stehen + dativo = quedarle bien a alguien",
  "Casual criticism, mild to sharp depending on tone — from amused head-shake about a friend to genuine warning about a date.": "Crítica informal, suave o afilada según el tono — desde el meneo de cabeza divertido por un amigo hasta la advertencia seria sobre una cita.",
  "Casual date invite (better than formal 'Möchten Sie...')": "Invitación a una cita en tono informal (mejor que el formal 'Möchten Sie...')",
  "Casual dating vocabulary with friends. The verb is fully germanized: ghosten, geghostet.": "Vocabulario informal de citas entre amigos. El verbo está germanizado del todo: ghosten, geghostet.",
  "Casual dating-discourse talk, mostly among friends dissecting someone's behaviour. Anglicism, feminine in German: die Red Flag (French keeps it masculine: un red flag).": "Charla informal sobre citas, sobre todo entre amigos que diseccionan el comportamiento de alguien. Anglicismo, femenino en alemán: die Red Flag (el francés lo mantiene masculino: un red flag).",
  "casual Denglisch — 'Ich hab gecodet' is completely normal among devs": "denglisch informal — 'Ich hab gecodet' es de lo más normal entre desarrolladores",
  "Casual directive": "Indicación informal",
  "Casual du-register. This is the pattern the seed word needs: anstoßen AUF + Akkusativ (auf den Erfolg, aufs neue Jahr, auf dich). Separable, so the prefix lands at the end: wir stoßen darauf an. And keep eye contact while clinking.": "Registro de du, informal. Este es el patrón que exige la palabra: anstoßen AUF + acusativo (auf den Erfolg, aufs neue Jahr, auf dich). Separable, así que el prefijo va al final: wir stoßen darauf an. Y mantén el contacto visual al brindar.",
  "Casual everyday goodbye — used everywhere in Germany": "Despedida informal de cada día — se usa en toda Alemania",
  "Casual everyday reassurance": "Frase de tranquilidad informal del día a día",
  "Casual favour between friends (du). 'drüberschauen' = give it a quick once-over.": "Favor informal entre amigos (du). 'drüberschauen' = echarle un vistazo rápido.",
  "Casual for playing video games; in money contexts it means to gamble.": "Informal para jugar a videojuegos; con dinero de por medio significa apostar.",
  "Casual goodbye — borrowed from Italian, extremely popular in Germany": "Despedida informal — tomada del italiano, muy popular en Alemania",
  "casual gym slang for lifting weights; 'pumpen gehen'": "argot informal de gimnasio para levantar pesas; 'pumpen gehen'",
  "Casual idiom, literally 'sponge over it' (wiping the slate): declares a small quarrel officially closed. Friends and partners, minor stuff only — don't 'Schwamm drüber' a real hurt.": "Modismo informal, literalmente 'esponja encima' (borrar la pizarra): declara oficialmente cerrada una pequeña discusión. Amigos y pareja, solo para cosas menores — una herida de verdad no se borra así.",
  "Casual imperative 'Investier' is common spoken German; full written form is 'Investiere'.": "El imperativo informal 'Investier' es habitual en el alemán hablado; la forma escrita completa es 'Investiere'.",
  "Casual imperative 'Markier' is common in voice chat; after 'damit', 'verlaufen' goes to the end.": "El imperativo informal 'Markier' es habitual en el chat de voz; tras 'damit', 'verlaufen' va al final.",
  "Casual imperative 'Setz' is short for 'Setze'; 'am' contracts dative 'an dem'.": "El imperativo informal 'Setz' abrevia 'Setze'; 'am' contrae el dativo 'an dem'.",
  "Casual imperative of separable 'hinzufügen' is 'Füg ... hinzu'; the person being added is accusative 'mich'.": "El imperativo informal del separable 'hinzufügen' es 'Füg ... hinzu'; la persona añadida va en acusativo: 'mich'.",
  "Casual invite": "Invitación informal",
  "Casual kitchen-table economics; sich lohnen = to be worth it — very high-frequency verb": "Economía informal de mesa de cocina; sich lohnen = merecer la pena — verbo muy frecuente",
  "casual loanword; einkaufen is the German verb": "préstamo informal; einkaufen es el verbo alemán",
  "Casual media criticism among friends; sich aufregen über = to get worked up about — essential B1 verb": "Crítica de los medios en tono informal entre amigos; sich aufregen über = enfadarse por — verbo esencial de B1",
  "casual money-vent to friends, du-register — the one informal line in this pack; the bank formally calls it 'Dispositionskredit'": "desahogo informal sobre dinero entre amigos, registro de du — la única línea informal de este paquete; el banco lo llama oficialmente 'Dispositionskredit'",
  "Casual opener": "Entrada de conversación informal",
  "Casual opener for close friends": "Entrada informal entre amigos cercanos",
  "Casual opinion": "Opinión informal",
  "Casual pointing-at-things question with friends — how learners actually acquire everyday nouns. 'das Ding' = thingy.": "Pregunta informal señalando cosas, entre amigos — así aprenden de verdad los sustantivos cotidianos quienes estudian. 'das Ding' = el chisme.",
  "Casual positive update": "Novedad positiva en tono informal",
  "Casual pub folklore — 'angeblich' (supposedly) does the honest work here. It's a myth: the Konterbier only postpones the hangover, and needing one regularly is a recognised warning sign.": "Folclore de bar informal — aquí es 'angeblich' (supuestamente) quien hace el trabajo honesto. Es un mito: la Konterbier solo aplaza la resaca, y necesitarla con regularidad es una señal de alarma reconocida.",
  "Casual register inside student life; durcharbeiten = work through without a break.": "Registro informal de la vida estudiantil; durcharbeiten = trabajar sin parar.",
  "Casual reminiscing; 'was los sein' = something happening.": "Recuerdos en tono informal; 'was los sein' = pasa algo.",
  "Casual reply": "Respuesta informal",
  "Casual request": "Petición informal",
  "Casual request to repeat": "Petición informal de que repitan",
  "Casual self-intro": "Presentación personal informal",
  "Casual slang command": "Orden en argot informal",
  "Casual slang farewell": "Despedida en argot informal",
  "Casual slang, friends only — two senses: \"count me out\" when plans are being made, or \"I'm off\" when you leave. From poker and reality TV, now everywhere among under-40s; abrupt to strangers or at work.": "Argot informal, solo entre amigos — dos sentidos: 'sin mí' cuando se hacen planes, o 'me largo' cuando te vas. Del póquer y la telerrealidad, hoy por todas partes entre menores de 40; brusco con desconocidos o en el trabajo.",
  "Casual speech drops the prefix: you 'schieben' a plan with a friend, you 'verschieben' a Termin with a doctor or a client. 'auf' + accusative for the new date.": "En el habla informal se cae el prefijo: un plan con un amigo se 'schiebt', un Termin con el médico o un cliente se 'verschiebt'. 'auf' + acusativo para la nueva fecha.",
  "Casual spoken imperative 'Markier' is common; the tool follows dative 'mit einem Bleistift'.": "El imperativo hablado informal 'Markier' es habitual; la herramienta va en dativo: 'mit einem Bleistift'.",
  "Casual spoken; 'ich wechsel' instead of textbook 'ich wechsle' is normal in speech. 'Die Klasse' is standard, no English loan here.": "Habla informal; 'ich wechsel' en lugar del 'ich wechsle' de los manuales es normal al hablar. 'Die Klasse' es lo estándar, aquí no hay préstamo inglés.",
  "casual spoken; from sich fertig machen = sich zurechtmachen": "habla informal; de sich fertig machen = arreglarse",
  "casual spoken; the machen-lassen pattern for anything done at a salon": "habla informal; el patrón machen-lassen para todo lo que se hace en un salón",
  "casual, admiring; 'definiert' = lean and cut, more technical": "informal y admirativo; 'definiert' = definido y marcado, más técnico",
  "CASUAL, and generational — 'geil' originally meant horny and is now simply 'awesome' in everyday speech, but older relatives still wince. The 'Wie ... ist das denn!' frame takes any adjective: 'Wie süß ist das denn!', 'Wie teuer ist das denn!'": "INFORMAL, y generacional — 'geil' significaba en origen cachondo y hoy es simplemente 'genial' en el habla diaria, pero los parientes mayores todavía hacen una mueca. El marco 'Wie ... ist das denn!' admite cualquier adjetivo: 'Wie süß ist das denn!', 'Wie teuer ist das denn!'",
  "Casual, concerned — 'die Spielothek' (slot arcade) sits several rungs below 'das Casino' in register and respectability; the sentence itself signals worry.": "Informal y preocupado — 'die Spielothek' (salón de máquinas) está varios peldaños por debajo de 'das Casino' en registro y respetabilidad; la frase misma señala inquietud.",
  "Casual, enthusiastic. 'Der Wahnsinn' is the go-to superlative among friends.": "Informal y entusiasta. 'Der Wahnsinn' es el superlativo de cabecera entre amigos.",
  "casual, everyday; \"dezent\" is THE German word for understated — makeup, jewellery, perfume, clothes — and its opposite is \"auffällig\". Fills the gap in this pack between the salon requests and the compliments: how you describe your own look. 'sich schminken' changes with the person: 'ich schminke mich', 'du schminkst dich'.": "informal, cotidiano; 'dezent' es LA palabra alemana para discreto — maquillaje, joyas, perfume, ropa — y su opuesto es 'auffällig'. Llena en este paquete el hueco entre las peticiones en la peluquería y los cumplidos: cómo describes tu propio aspecto. 'sich schminken' cambia con la persona: 'ich schminke mich', 'du schminkst dich'.",
  "casual, everyday; der Lidstrich is the German word, Eyeliner is what people say": "informal, cotidiano; der Lidstrich es la palabra alemana, pero la gente dice Eyeliner",
  "Casual, exasperated. Standard lakeside-evening lament; 'fressen' (animal eating) makes it vivid.": "Informal y exasperado. El lamento clásico de una tarde junto al lago; 'fressen' (comer, de animales) lo hace muy gráfico.",
  "Casual, mild — amused disbelief among friends and family. Friendly in tone, but too blunt for strangers or superiors.": "Informal, suave — incredulidad divertida entre amigos y familia. Amistoso en tono, pero demasiado directo para desconocidos o superiores.",
  "Casual, mild — the adjective version, interchangeable with 'einen Kater haben'. Fine in any informal setting.": "Informal, suave — la versión adjetiva, intercambiable con 'einen Kater haben'. Vale en cualquier contexto informal.",
  "Casual, mild — the standard morning-after sentence among friends and relaxed colleagues. 'fett' intensifies it.": "Informal, suave — la frase estándar de la mañana siguiente entre amigos y compañeros de confianza. 'fett' la intensifica.",
  "Casual, mild — the standard verdict on a Flachwitz. Said with a groan and half a smile; friends and colleagues.": "Informal, suave — el veredicto estándar sobre un Flachwitz. Dicho con un gruñido y media sonrisa; amigos y compañeros.",
  "Casual, playful — everyday micro-betting between friends. 'die Wette' = the bet; the structure was immortalized by the TV show 'Wetten, dass..?'.": "Informal, juguetón — la microapuesta cotidiana entre amigos. 'die Wette' = la apuesta; la estructura la inmortalizó el programa de televisión 'Wetten, dass..?'.",
  "Casual, relieved-triumphant, to friends. 'überstehen' = to survive something unpleasant.": "Informal, con alivio triunfal, entre amigos. 'überstehen' = sobrevivir a algo desagradable.",
  "Casual, relieved. 'Kriegen' is the everyday spoken 'bekommen'. Rare Bahn stories have happy endings — savour them.": "Informal, aliviado. 'Kriegen' es el 'bekommen' hablado de cada día. Pocas historias de tren acaban bien — saboréalas.",
  "Casual, teasing — literally 'do you have tomatoes on your eyes?'": "Informal y burlón — literalmente '¿tienes tomates en los ojos?'",
  "Casual, to companions. Famous last words on any hike.": "Informal, a los acompañantes. Las últimas palabras célebres de cualquier caminata.",
  "Casual, to family/friends. Brotzeit = bread, cheese, sausage — the mandatory trail picnic, especially in the south.": "Informal, a familia y amigos. Brotzeit = pan, queso, embutido — el picnic obligatorio de la ruta, sobre todo en el sur.",
  "Casual, to friends. The flat-rate monthly ticket for all regional transport — changed how Germans plan day trips.": "Informal, a los amigos. El abono mensual de tarifa plana para todo el transporte regional — cambió cómo planifican los alemanes sus excursiones de un día.",
  "Casual, to friends/partner. 'An den See fahren' is the German summer ritual — pack the Picknick.": "Informal, a amigos o a la pareja. 'An den See fahren' es el ritual veraniego alemán — prepara el Picknick.",
  "Casual, to one person (du) — group: Lasst uns anfangen; formal: Fangen wir an": "Informal, a una persona (du) — al grupo: Lasst uns anfangen; formal: Fangen wir an",
  "Casual, universal. The standard excuse to step outside — nobody questions frische Luft.": "Informal, universal. La excusa estándar para salir fuera — nadie cuestiona el frische Luft.",
  "Casual, wry — literally 'life is no pony farm'": "Informal e irónico — literalmente 'la vida no es una granja de ponis'",
  "casual, younger speakers; Hautpflege is the more formal word": "informal, hablantes jóvenes; Hautpflege es la palabra más formal",
  "Casual; 'die Pause' is the break, 'der Pausenhof' the yard it happens on.": "Informal; 'die Pause' es el recreo, 'der Pausenhof' el patio donde ocurre.",
  "casual; 'platt' = wiped out, works for any exhaustion": "informal; 'platt' = hecho polvo, sirve para cualquier agotamiento",
  "casual; 'Proteinshake' works too": "informal; 'Proteinshake' también vale",
  "casual; 'pumpen gehen' marks you as a weights person, not a treadmill person": "informal; 'pumpen gehen' te marca como persona de pesas, no de cinta de correr",
  "casual; 'sich etwas ziehen' = to pull a muscle": "informal; 'sich etwas ziehen' = darse un tirón muscular",
  "Casual; ackern makes the work sound tiring or relentless.": "Informal; ackern hace que el trabajo suene agotador e implacable.",
  "Casual; adults admit it with a grin": "Informal; los adultos lo admiten con una sonrisa",
  "casual; literally also to plough a field": "informal; literalmente también arar un campo",
  "casual; stechen lassen (literally 'have it pricked') is the idiomatic verb for tattoos": "informal; stechen lassen (literalmente 'hacerse pinchar') es el verbo idiomático para los tatuajes",
  "casual; the question everyone asks": "informal; la pregunta que todo el mundo hace",
  "casual; the standard (optimistic) answer": "informal; la respuesta típica (optimista)",
  "Casual; the way adults confess it with a grin.": "Informal; así lo confiesan los adultos con una sonrisa.",
  "casual: kicken gehen = to go and play football": "informal: kicken gehen = ir a jugar al fútbol",
  "Casual. 'Baden gehen' = swim outdoors (lake, sea); 'schwimmen gehen' leans towards the pool.": "Informal. 'Baden gehen' = bañarse al aire libre (lago, mar); 'schwimmen gehen' tira más a la piscina.",
  "Casual. 'Eine Runde drehen' = do a loop; works for walks, bike rides or a quick drive.": "Informal. 'Eine Runde drehen' = dar una vuelta; sirve para paseos, salidas en bici o un trayecto corto en coche.",
  "Casual. 'Sich etwas holen' = to catch/get something (sunburn, a cold).": "Informal. 'Sich etwas holen' = pillar algo (una quemadura solar, un resfriado).",
  "casually clipped to 'der Elfer'": "recortado coloquialmente a 'der Elfer'",
  "Cheerful surrender to one good argument, not to the whole debate — said with a laugh, and very often followed by 'aber trotzdem ...'. German needs the 'erwischt': bare 'Da hast du mich' sounds unfinished. Fine with friends and colleagues; in a real row the same words come out sarcastic, so save it for when you're smiling.": "Rendición alegre ante un buen argumento, no ante todo el debate — dicho con una risa y muy a menudo seguido de 'aber trotzdem ...'. El alemán necesita el 'erwischt': el escueto 'Da hast du mich' suena inacabado. Vale con amigos y compañeros; en una discusión de verdad las mismas palabras salen sarcásticas, así que guárdalas para cuando sonríes.",
  "Chores": "Tareas de casa",
  "Clean fault-owning, no hedging — respected in relationships and at work alike. The clipped 'Mein Fehler' is the casual 'my bad' for small stuff.": "Asumir la culpa con limpieza, sin rodeos — se respeta igual en las relaciones que en el trabajo. El escueto 'Mein Fehler' es la versión informal para cosas pequeñas.",
  "close friends only — sharing a cigarette or vape": "solo entre amigos cercanos — compartir un cigarrillo o un vaper",
  "Coarse — stronger than 'das ist mir egal'. Friends only; rude if said to a teacher, boss, or official.": "Basto — más fuerte que 'das ist mir egal'. Solo entre amigos; grosero ante un profesor, un jefe o un funcionario.",
  "Coarse and common among friends. It can sound confrontational when said angrily.": "Basto y habitual entre amigos. Dicho con rabia puede sonar a desafío.",
  "Coarse and common. With a smile it can show disbelief among friends; with an angry voice it accuses someone of messing with you.": "Basto y común. Con una sonrisa expresa incredulidad entre amigos; con voz enfadada acusa a alguien de estar tomándote el pelo.",
  "Coarse-casual — 'forget it, who cares'. Banter-safe among friends; not for formal company.": "Basto e informal — 'olvídalo, qué más da'. Vale como broma entre amigos; no en compañía formal.",
  "Coarse-casual — 'zum Kotzen' (enough to make you vomit) is the strong end of 'that was terrible'. Friends and family, not the office.": "Basto e informal — 'zum Kotzen' (como para vomitar) es el extremo fuerte de 'fue horrible'. Amigos y familia, no la oficina.",
  "Coarse-casual — Scheiß- glues onto any noun (Scheißwetter, Scheißjob, Scheißauto). Friends and family, not the office.": "Basto e informal — Scheiß- se pega a cualquier sustantivo (Scheißwetter, Scheißjob, Scheißauto). Amigos y familia, no la oficina.",
  "Coarse-colloquial and strong — 'Schnauze' is an animal's snout, so this is blunt, borderline-rude frustration for partners and friends, never the office. The polite sibling is 'Ich hab die Nase voll' (nose instead of snout), safe anywhere.": "Basto-coloquial y fuerte — 'Schnauze' es el hocico de un animal, así que es una frustración directa, al borde de la grosería, para pareja y amigos, nunca para la oficina. El hermano educado es 'Ich hab die Nase voll' (nariz en lugar de hocico), seguro en todas partes.",
  "coden is casual Denglisch; completely normal in the du-form dev crowd.": "coden es denglisch informal; de lo más normal en el mundillo dev que se tutea.",
  "Colloquial (Kopfnuss = headbutt/noogie)": "Coloquial (Kopfnuss = cabezazo o coscorrón)",
  "Colloquial and openly insulting — fine among friends, rude about strangers. Milder alternatives are blöd and doof.": "Coloquial y abiertamente insultante — vale entre amigos, grosero sobre desconocidos. Alternativas más suaves son blöd y doof.",
  "Colloquial and strong; covers verbal and psychological cruelty, not just physical.": "Coloquial y fuerte; abarca la crueldad verbal y psicológica, no solo la física.",
  "Colloquial and strong; verbal or psychological cruelty": "Coloquial y fuerte; crueldad verbal o psicológica",
  "colloquial and very common; 'Funkstille' is the go-to image for a communication freeze in families": "coloquial y muy común; 'Funkstille' es la imagen recurrente del silencio total en las familias",
  "colloquial anglicism (Duden-listed); marketing and social media register": "anglicismo coloquial (recogido en el Duden); registro de marketing y redes sociales",
  "Colloquial but harmless — safe with colleagues and family.": "Coloquial pero inofensivo — seguro con compañeros y familia.",
  "Colloquial but harmless — the polite cousin of 'verarschen'. Safe with colleagues, in-laws, anyone informal.": "Coloquial pero inofensivo — el primo educado de 'verarschen'. Seguro con compañeros, suegros, cualquiera en registro informal.",
  "Colloquial but serious; 'zu dritt' = three of them together.": "Coloquial pero serio; 'zu dritt' = entre tres.",
  "Colloquial combo of Ja + Nein": "Mezcla coloquial de Ja + Nein",
  "Colloquial fixed expression meaning that someone loses their nerve or retreats. It is not sexual in this use.": "Expresión fija coloquial que significa que alguien se acobarda o se echa atrás. En este uso no tiene sentido sexual.",
  "colloquial for lowering graphics or volume: 'die Grafik runterdrehen'. Formal 'herunterdrehen' sounds stiff in speech": "coloquial para bajar los gráficos o el volumen: 'die Grafik runterdrehen'. El formal 'herunterdrehen' suena rígido al hablar",
  "Colloquial idiom, mild — groaning at a joke everyone has heard a hundred times. Friends and casual colleagues.": "Modismo coloquial, suave — el gruñido ante un chiste que todos han oído cien veces. Amigos y compañeros de confianza.",
  "colloquial intensifier: mächtig stolz = mighty proud": "intensificador coloquial: mächtig stolz = orgullosísimo",
  "Colloquial northern greeting — standard from Hamburg to the Danish border, at any hour of the day, and it will mark you out anywhere south of it.": "Saludo coloquial del norte — estándar desde Hamburgo hasta la frontera danesa, a cualquier hora del día, y más al sur te delatará.",
  "Colloquial sarcasm, mild-moderate — mock admiration for a mess or fiasco. Friends and casual colleagues; literally 'really big cinema'.": "Sarcasmo coloquial, suave o moderado — admiración fingida ante un desastre o un fiasco. Amigos y compañeros de confianza; literalmente 'gran cine'.",
  "Colloquial short form of herauskommen; also used of films, products or models being released.": "Forma corta coloquial de herauskommen; también para películas, productos o modelos que salen.",
  "Colloquial shortcut": "Atajo coloquial",
  "Colloquial southern greeting, and one of the few that works at both ends of a conversation. In the north it reads as visiting.": "Saludo coloquial del sur, y uno de los pocos que funciona al principio y al final de una conversación. En el norte suena a visita.",
  "Colloquial, mild — casual settings with friends, family, relaxed colleagues. Often typed in chats too.": "Coloquial, suave — contextos informales con amigos, familia, compañeros de confianza. También se escribe mucho en chats.",
  "Colloquial, mild — gasped mid-laughter or typed in chats. Friends, family, relaxed colleagues.": "Coloquial, suave — soltado entre risas o escrito en un chat. Amigos, familia, compañeros de confianza.",
  "Colloquial, mild — genuine ('der Brüller' = a roar of laughter) or ironic for something boring. Friends and casual settings.": "Coloquial, suave — sincero ('der Brüller' = una carcajada) o irónico para algo aburrido. Amigos y contextos informales.",
  "Colloquial, mild — telling anyone informally how funny something was. sich kaputtlachen = laugh yourself 'broken'.": "Coloquial, suave — para contarle a cualquiera de manera informal lo gracioso que fue. sich kaputtlachen = reírse hasta 'romperse', partirse de risa.",
  "Colloquial, rueful — literal at the casino, figurative for blowing a lead or chance. 'der Gewinn' (winnings) and 'der Verlust' (loss) are the accounting pair that goes with it.": "Coloquial, con pesar — literal en el casino, figurado cuando se dilapida una ventaja o una oportunidad. 'der Gewinn' (las ganancias) y 'der Verlust' (la pérdida) son el par contable que lo acompaña.",
  "colloquial, what children do in sand; graben is neutral": "coloquial, lo que hacen los niños en la arena; graben es neutro",
  "Colloquial; 'sich prügeln' is physical, much stronger than 'sich streiten'.": "Coloquial; 'sich prügeln' es físico, mucho más fuerte que 'sich streiten'.",
  "colloquial; invariable: ein super Film": "coloquial; invariable: ein super Film",
  "colloquially also snappy, punchy (UI, prose, deadlines)": "coloquialmente también ágil, contundente (interfaces, textos, plazos)",
  "colloquially shortened to 'das Gespräch'": "acortado coloquialmente a 'das Gespräch'",
  "Colloquially, Der Hammer! means amazing or awesome — the literal tool is the primary card meaning.": "Coloquialmente, Der Hammer! significa genial — pero el sentido principal de la tarjeta es la herramienta.",
  "common and informal; can describe a person, idea or situation": "habitual e informal; puede describir a una persona, una idea o una situación",
  "Common complaint": "Queja frecuente",
  "Common slang reaction": "Reacción habitual en argot",
  "Common slang reaction to bad news — mies = lousy, shabby": "Reacción habitual en argot ante malas noticias — mies = malo, cutre",
  "Comprehension note for adult informal German. The neutral anatomy word is 'Penis'; 'Schwanz' has roughly the force of English 'dick'.": "Nota de comprensión para el alemán informal de adultos. La palabra anatómica neutra es 'Penis'; 'Schwanz' tiene aproximadamente la fuerza del inglés 'dick'.",
  "Confirming": "Confirmar",
  "Confrontational warning after being insulted — it escalates, not calms. Understand it as 'you're one word away from real trouble'.": "Advertencia de confrontación tras un insulto — escala, no calma. Se entiende como 'estás a una palabra de un problema de verdad'.",
  "Consent": "Consentimiento",
  "Consent — always check": "Consentimiento — pregunta siempre",
  "Conversational geopolitics with an opinion baked in — fine among friends, spicier at work": "Geopolítica de conversación con opinión incorporada — bien entre amigos, más delicado en el trabajo",
  "Core repair line after words that cut too deep — tender, serious, for partners, family, close friends. Follow it with what you DID mean, or it hangs in the air.": "La frase reparadora esencial tras palabras que cortaron demasiado hondo — tierna, seria, para pareja, familia, amigos cercanos. Sigue con lo que SÍ querías decir, o se queda flotando en el aire.",
  "Crude but affectionate — literally 'throw up on you'. Close friends only, never a colleague you don't know well. The tearful version is 'sich bei jemandem ausheulen'.": "Crudo pero cariñoso — literalmente 'vomitarle a alguien encima'. Solo amigos cercanos, nunca un compañero al que apenas conoces. La versión llorosa es 'sich bei jemandem ausheulen'.",
  "Crude for people (fine among friends, marks heavy drinking); for animals it is simply the neutral word for 'to drink'.": "Crudo para personas (vale entre amigos, señala beber en exceso); para animales es simplemente la palabra neutra para beber.",
  "Crude-ish colloquial, from saufen. Fine among friends, carries a judgy or comic undertone; not for formal settings.": "Lenguaje coloquial más bien crudo, de saufen. Vale entre amigos, con un trasfondo de juicio o de comicidad; no para contextos formales.",
  "Crude-ish colloquial, mildly judgy or comic — friends and family only. The neutral word for reports and polite company is 'betrunken'.": "Lenguaje coloquial más bien crudo, algo enjuiciador o cómico — solo amigos y familia. La palabra neutra para informes y compañía educada es 'betrunken'.",
  "Crude, self-deprecating — friends only. 'saufen' always signals heavy drinking; never use it about someone in a serious context.": "Crudo, autoirónico — solo entre amigos. 'saufen' siempre señala beber en exceso; nunca lo uses sobre alguien en un contexto serio.",
  "dark humour among friends; 'Echsenmenschen' is the go-to absurd-conspiracy reference": "humor negro entre amigos; 'Echsenmenschen' es la referencia típica a las conspiraciones absurdas",
  "das Band — the conveyor. Braking on it is the one real mistake to avoid.": "das Band — la cinta transportadora. Frenar encima es el único error de verdad que hay que evitar.",
  "das Bügeleisen — the iron. The warning every household repeats.": "das Bügeleisen — la plancha. La advertencia que repite cada casa.",
  "das Halbjahreszeugnis — the February report. The early warning system.": "das Halbjahreszeugnis — el boletín de febrero. El sistema de alerta temprana.",
  "Das hängt davon ab = it depends. Casually, mit Freunden abhängen = to hang out.": "Das hängt davon ab = depende. En tono informal, mit Freunden abhängen = pasar el rato con amigos.",
  "das Profil — the tread. 'ist runter' — worn away; casual passive Germany runs on.": "das Profil — el dibujo del neumático. 'ist runter' — gastado; la pasiva informal sobre la que rueda Alemania.",
  "das Rücklicht — the rear light. 'nur noch schwach' — the warning phase before darkness.": "das Rücklicht — la luz trasera. 'nur noch schwach' — la fase de aviso antes de la oscuridad.",
  "das Spritgeld — the fuel share. Simple beats fair-to-the-cent; friendships prefer round numbers.": "das Spritgeld — la parte de la gasolina. Lo simple gana a lo justo al céntimo; las amistades prefieren números redondos.",
  "das Teil — the casual word for any piece of clothing. The rule that prevents the pink wash.": "das Teil — la palabra informal para cualquier prenda. La regla que evita la colada rosa.",
  "das Wartezimmer — from the doctor pack, considerably louder. Cats sit high; dogs make friends.": "das Wartezimmer — del paquete del médico, bastante más ruidosa. Los gatos se ponen en alto; los perros hacen amigos.",
  "Dating": "Citas",
  "Dative again: 'mir ist übel', never 'ich bin übel'. Watch the double life of the word — under-25s use bare 'übel' as slang for insane/awesome ('übel gut'), but 'Mir ist übel' only ever means nausea.": "Otra vez el dativo: 'mir ist übel', nunca 'ich bin übel'. Ojo con la doble vida de la palabra — los menores de 25 usan 'übel' a secas como argot para 'brutal, genial' ('übel gut'), pero 'Mir ist übel' solo significa náuseas.",
  "Deadpan irony, mild — the standard flat response when someone teases you. Safe with anyone informal; can sound genuinely annoyed if said sharply.": "Ironía impasible, suave — la respuesta plana estándar cuando alguien te pincha. Segura con cualquiera en registro informal; dicha con filo puede sonar realmente molesta.",
  "Deadpan sarcasm, mild — the everyday ironic groan at bad news. Universal: friends, family, muttered at work.": "Sarcasmo impasible, suave — el gruñido irónico de cada día ante malas noticias. Universal: amigos, familia, mascullado en el trabajo.",
  "Deliberately vague — it lets both sides keep it casual. 'was' here is short for 'etwas'.": "Deliberadamente vago — deja que ambas partes lo mantengan informal. Aquí 'was' es la forma corta de 'etwas'.",
  "Denglish gym slang, completely standard between lifters; more formal: 'Kannst du mir Hilfestellung geben?'": "Argot de gimnasio en denglish, de lo más estándar entre quienes levantan; más formal: 'Kannst du mir Hilfestellung geben?'",
  "der Aszendent — the follow-up question that separates casual from committed.": "der Aszendent — la repregunta que separa a los curiosos de los convencidos.",
  "der Blitzer = speed camera (colloquial); note: radar-warning apps are illegal to use while driving in Germany (§ 23 StVO)": "der Blitzer = radar (coloquial); nota: las apps avisadoras de radares son ilegales al volante en Alemania (§ 23 StVO)",
  "der Helferkreis — the informal volunteer group, common in refugee and neighbourhood support.": "der Helferkreis — el grupo de voluntarios informal, habitual en el apoyo a refugiados y de barrio.",
  "der Platten — the flat tyre, colloquial and universal. The commute's classic opening line.": "der Platten — el pinchazo, coloquial y universal. La frase clásica para abrir la charla del trayecto.",
  "der Strafzettel, colloquially das Knöllchen = parking ticket": "der Strafzettel, coloquialmente das Knöllchen = multa de aparcamiento",
  "Desire": "Deseo",
  "die Abmahnung — the warning shot, at work or over copyright. Serious, not final.": "die Abmahnung — el aviso serio, en el trabajo o por derechos de autor. Grave, pero no definitivo.",
  "die Abmahnung — the written warning. Serious, but far from a dismissal.": "die Abmahnung — la amonestación por escrito. Grave, pero muy lejos de un despido.",
  "die Bescherung = the ritual gift-opening moment on Heiligabend; every family defends its own timing (before church, after dinner, after the carols). Warning: 'Da haben wir die Bescherung!' as an exclamation ironically means 'now we're in a fine mess'.": "die Bescherung = el momento ritual de abrir los regalos en Nochebuena; cada familia defiende su propio horario (antes de misa, después de la cena, tras los villancicos). Aviso: 'Da haben wir die Bescherung!' como exclamación significa irónicamente 'ya la hemos liado'.",
  "die DM, pronounced 'deh-em'; 'ne' = clipped 'eine'. Neutral-casual — the full German 'private Nachricht' sounds oddly formal now.": "die DM, pronunciado 'de-em'; 'ne' = 'eine' recortado. Neutro-informal — el completo alemán 'private Nachricht' hoy suena raramente formal.",
  "die Hausnummer — colloquial for a rough figure. More with a role change.": "die Hausnummer — coloquial para una cifra aproximada. Más si cambia el puesto.",
  "die Jugendfeuerwehr — where most volunteers begin. Knots, hoses and friendships.": "die Jugendfeuerwehr — donde empiezan la mayoría de los voluntarios. Nudos, mangueras y amistades.",
  "die Kantine — the subsidised lunch. The invitation that builds actual friendships.": "die Kantine — la comida subvencionada. La invitación de la que salen amistades de verdad.",
  "die Laune = mood. Owning the mood stops it becoming a fight. Colloquial synonym: 'Ich bin schlecht drauf.' Opposite: gute Laune / gut drauf.": "die Laune = el humor. Asumir el propio humor evita que se convierta en pelea. Sinónimo coloquial: 'Ich bin schlecht drauf.' Contrario: gute Laune / gut drauf.",
  "die Lawine — the avalanche. The warning is not decorative.": "die Lawine — la avalancha. La advertencia no es decorativa.",
  "die Leitung = the phone line (also the cable from your ISP, and 'eine lange Leitung haben' = to be slow on the uptake). Hanging up and redialling is the universal German fix — announcing it first stops the other person thinking you hung up on them. 'mies' is casual for lousy.": "die Leitung = la línea telefónica (también el cable del proveedor, y 'eine lange Leitung haben' = ser lento de entendederas). Colgar y volver a llamar es el remedio universal alemán — anunciarlo antes evita que el otro crea que le has colgado. 'mies' es el término informal para pésimo.",
  "Direct and neutral: 'Ich bin schwanger.' Colloquially, 'schwanger von ihm' names the father.": "Directo y neutro: 'Ich bin schwanger.' Coloquialmente, 'schwanger von ihm' nombra al padre.",
  "draufgehen (colloquial) = gets eaten up; die Abgaben = social contributions on top of taxes; casual complaining": "draufgehen (coloquial) = se lo come todo; die Abgaben = las cotizaciones sociales además de los impuestos; queja informal",
  "drohen with a thing as subject = to loom/threaten to occur: Dehydrierung droht. sonst carries the warning.": "drohen con una cosa como sujeto = amenazar con producirse: Dehydrierung droht. sonst lleva la advertencia.",
  "Du form, between friends. French speakers in Germany keep the word 'Bürgeramt'. Appointments are notoriously scarce in big cities — book the moment you know you're moving.": "Forma de du, entre amigos. Los francófonos en Alemania conservan la palabra 'Bürgeramt'. Las citas escasean notoriamente en las ciudades grandes — reserva en cuanto sepas que te mudas.",
  "du-form for friends and partners. With strangers or officials: 'Können Sie das bitte wiederholen?'": "Forma de du para amigos y pareja. Con desconocidos o funcionarios: 'Können Sie das bitte wiederholen?'",
  "Du-form, friends and family. 'gerade' (usually swallowed to 'grad') carries the 'right now' — leave it out and you sound like you're asking whether they are physically capable of speech.": "Forma de du, amigos y familia. 'gerade' (normalmente reducido a 'grad') aporta el 'ahora mismo' — si lo quitas, suena a que preguntas si la persona es físicamente capaz de hablar.",
  "düngen = to fertilize; der Dünger = fertilizer. Du register — said between family/friends": "düngen = abonar; der Dünger = el abono. Registro de du — se dice entre familia y amigos",
  "eh = anyway / in any case (colloquial 'ohnehin')": "eh = de todos modos / en cualquier caso (coloquial por 'ohnehin')",
  "eine Runde schmeißen — literally throwing a round. Casual, generous, slightly theatrical.": "eine Runde schmeißen — literalmente lanzar una ronda. Informal, generoso, un poco teatral.",
  "Emergency": "Emergencia",
  "Emphasis": "Énfasis",
  "Emphatic casual yes": "Sí informal y enfático",
  "Encouragement between friends or from a partner — the compliment learners most want to hear.": "Ánimo entre amigos o de la pareja — el cumplido que más quieren oír quienes aprenden.",
  "Enemy info": "Info del enemigo",
  "English loan, fully naturalized and plural; 'doch' makes it dismissive — casual register": "préstamo del inglés, plenamente naturalizado y en plural; 'doch' lo vuelve despectivo — registro informal",
  "Enthusiastic yes": "Sí entusiasta",
  "Erwischen = catching red-handed, in the act or via messages. The hinge word of every cheating story — expect friends to ask 'Wie hast du's rausgefunden?'": "Erwischen = pillar con las manos en la masa, en directo o por mensajes. La palabra bisagra de toda historia de infidelidad — cuenta con que los amigos pregunten: 'Wie hast du's rausgefunden?'",
  "Essential": "Imprescindible",
  "everyday casual word; also means the stubbed-out butt": "palabra informal de cada día; también significa la colilla apagada",
  "Everyday colloquial spelling of nichts": "Grafía coloquial cotidiana de nichts",
  "Everyday connection method (slang 'schreib mir')": "Manera cotidiana de mantener el contacto (argot 'schreib mir')",
  "Everyday criticism, medium weight; fine in casual talk about colleagues or exes.": "Crítica cotidiana de peso medio; vale en una charla informal sobre compañeros o ex.",
  "Everyday office and friend request; rüberschicken (send over) is the casual variant.": "Petición cotidiana en la oficina y entre amigos; rüberschicken (mandar) es la variante informal.",
  "Everyday slang (Bock haben)": "Argot cotidiano (Bock haben)",
  "Everyday slang (spendieren = to treat)": "Argot cotidiano (spendieren = invitar)",
  "Excited announcement to friends and family. Once the context is clear, everyone just says 'Gespräch'.": "Anuncio emocionado a amigos y familia. Una vez claro el contexto, todos dicen simplemente 'Gespräch'.",
  "Extremely common in speech as a hedge: Das ist quasi dasselbe. Latin by origin, fully casual in use.": "Muy común en el habla como atenuante: Das ist quasi dasselbe. De origen latino, de uso totalmente informal.",
  "Facharzt = specialist; colloquially also \"einen Termin ausmachen\"": "Facharzt = médico especialista; coloquialmente también 'einen Termin ausmachen'",
  "Falschparken = illegal/incorrect parking": "Falschparken = aparcar mal o donde no se debe",
  "False friend warning: this is only appointment in the sense of naming someone to a position (die Ernennung zum Professor). A diary appointment is der Termin.": "Aviso de falso amigo: esto es solo el nombramiento para un puesto (die Ernennung zum Professor). Una cita en la agenda es der Termin.",
  "Family": "Familia",
  "Famous last words — friends will quote it back at you for months.": "Últimas palabras célebres — tus amigos te lo repetirán durante meses.",
  "Farewell": "Despedida",
  "Feeling": "Sentimiento",
  "feiern = to celebrate, colloquially 'to love something'; very current usage.": "feiern = celebrar, coloquialmente 'flipar con algo'; uso muy actual.",
  "fett = huge (colloquial intensifier); standard dev talk, not rude.": "fett = enorme (intensificador coloquial); jerga dev habitual, no es grosero.",
  "Finding help": "Buscar ayuda",
  "firm but civil pushback; the 'doch längst' signals mild exasperation — fine with family, friends, colleagues": "réplica firme pero cortés; el 'doch längst' marca una leve exasperación — vale en familia, con amigos y compañeros",
  "Fixed casual set expression; already short, so no further clipping.": "Expresión fija informal; ya es corta, así que no se recorta más.",
  "flach and steil around dahinter — the swimming-pool warning as a geometry lesson.": "flach y steil en torno a dahinter — la advertencia de la piscina como clase de geometría.",
  "Flight status update": "Estado del vuelo",
  "Flirting": "Ligar",
  "For dressing yourself up, say 'Ich verkleide mich als Pirat'. The casual question is 'Als was gehst du?' = what are you going as? 'das Kostüm' = the costume. At Rhineland Karneval, no costume marks you as a tourist or a grump.": "Para disfrazarte tú, di 'Ich verkleide mich als Pirat'. La pregunta informal es 'Als was gehst du?' = ¿de qué vas? 'das Kostüm' = el disfraz. En el carnaval renano, ir sin disfraz te marca como turista o aguafiestas.",
  "For getting yourself ready, say 'sich zurechtmachen': 'Ich mache mich zurecht.' The casual spoken version is 'sich fertig machen'.": "Para arreglarte, di 'sich zurechtmachen': 'Ich mache mich zurecht.' La versión hablada informal es 'sich fertig machen'.",
  "For people who have your number saved and know your voice — partner, family, close friends. 'bin's' = 'bin es'; the full 'Ich bin es' sounds oddly stiff out loud.": "Para quienes tienen tu número guardado y reconocen tu voz — pareja, familia, amigos cercanos. 'bin's' = 'bin es'; el completo 'Ich bin es' suena raramente rígido en voz alta.",
  "Formal": "Formal",
  "FORMAL — Sie-form, for a receptionist, a landlord, a client. With 'passen' the day itself is the subject ('Dienstag passt mir'), so you say 'Passt Ihnen Dienstag?', never 'Passt es Ihnen am Dienstag'. The verb is the same everyday 'passen' you use with friends; only the pronoun goes up a level.": "FORMAL — forma de Sie, para una recepción, un casero, un cliente. Con 'passen' el sujeto es el propio día ('Dienstag passt mir'), así que se dice 'Passt Ihnen Dienstag?', nunca 'Passt es Ihnen am Dienstag'. El verbo es el mismo 'passen' cotidiano que usas con amigos; solo sube de nivel el pronombre.",
  "FORMAL — the closing line of every delay announcement, ever. Between friends it's a joke: deliver any bad news, then add 'Wir bitten um Ihr Verständnis' with a straight face and the Bahn reference lands instantly.": "FORMAL — la frase de cierre de toda megafonía de retraso, siempre. Entre amigos es un chiste: da cualquier mala noticia y añade 'Wir bitten um Ihr Verständnis' con cara seria; la referencia a la Bahn cae al instante.",
  "FORMAL — your last warning on the platform. 'selbsttätig' is a wonderfully stiff old word for 'automatically' that has survived almost nowhere outside railway announcements.": "FORMAL — tu última advertencia en el andén. 'selbsttätig' es una palabra antigua maravillosamente rígida para 'automáticamente', que apenas ha sobrevivido fuera de los avisos ferroviarios.",
  "Friendly disbelief between friends — 'den' stands for der Film or der Song. Delivered flat and without a grin it reads as contempt, so keep the eyebrows involved.": "Incredulidad amistosa entre amigos — 'den' se refiere a der Film o der Song. Dicho plano y sin sonrisa suena a desprecio, así que que las cejas participen.",
  "Friends commonly drop 'Das' and the final e in 'finde'. The full form remains correct and is useful in careful speech.": "Entre amigos se suele omitir 'Das' y la -e final de 'finde'. La forma completa sigue siendo correcta y sirve en un habla cuidada.",
  "Frustrated, to friends. 'schon wieder' carries the job-hunt fatigue.": "Con frustración, entre amigos. 'schon wieder' lleva el cansancio de buscar trabajo.",
  "geblitzt werden = to get caught by a speed camera — the standard colloquial verb for it": "geblitzt werden = que te pille un radar — el verbo coloquial estándar para eso",
  "Gen-Z": "Gen Z",
  "Genuine compliment between friends; on a date it's practically flirting.": "Cumplido de verdad entre amigos; en una cita es prácticamente coquetear.",
  "Genuine distress, not everyday tiredness — this is a step past 'Ich bin total fertig' and friends will hear it as a real signal.": "Angustia de verdad, no cansancio cotidiano — esto está un escalón por encima de 'Ich bin total fertig', y los amigos lo oirán como una señal real.",
  "gereizt — irritable, like a nerve already touched. Fair warning to the room.": "gereizt — irritable, como un nervio ya tocado. Un aviso justo para toda la sala.",
  "German friends genuinely text each other their IBAN — it isn't treated as sensitive the way a card number is. Payment apps exist, but the plain bank transfer is still the default between adults.": "Los amigos alemanes se mandan de verdad su IBAN por mensaje — no se trata como algo tan sensible como un número de tarjeta. Existen apps de pago, pero la simple transferencia bancaria sigue siendo lo normal entre adultos.",
  "German has no word for 'playdate' — 'zum Spielen kommen' is how you actually arrange one. The 'mal' keeps it casual and easy to decline, which is exactly the point.": "El alemán no tiene palabra para 'playdate' — 'zum Spielen kommen' es como se organiza en realidad. El 'mal' lo mantiene informal y fácil de rechazar, que es justo el objetivo.",
  "German has three words for 'you': du to one friend, ihr to several friends, Sie to a stranger. The same question is Woher kommst du? and Woher kommen Sie?": "El alemán tiene tres palabras para 'tú': du a un amigo, ihr a varios amigos, Sie a un desconocido. La misma pregunta es Woher kommst du? y Woher kommen Sie?",
  "gib — du-imperative of geben with vowel change; mal keeps it casual, not bossy.": "gib — imperativo de du de geben con cambio vocálico; mal lo mantiene informal, no mandón.",
  "Greeting": "Saludo",
  "Grufti = colloquial for goth (from Gruft = tomb/crypt)": "Grufti = coloquial para gótico (de Gruft = cripta, tumba)",
  "Gunsmith": "Armería",
  "Half-joking household rule for the unsortable. Colloquial, said with a shrug.": "Norma casera medio en broma para lo que no se puede clasificar. Coloquial, dicho encogiéndose de hombros.",
  "half-joking quitter's line; 'ich schwör' is casual spoken German": "frase medio en broma de quien lo deja; 'ich schwör' es alemán hablado informal",
  "Half-joking threat when someone won't stop talking. Among friends it's banter; from a moderator it's a real sanction.": "Amenaza medio en broma cuando alguien no para de hablar. Entre amigos es una chanza; de un moderador es una sanción de verdad.",
  "happig = steep/hefty (colloquial). German utilities charge a monthly Abschlag (installment); the annual Abrechnung can bring a painful Nachzahlung (back payment)": "happig = salado, fuerte (coloquial). Las compañías alemanas cobran un Abschlag mensual (a cuenta); la liquidación anual (Abrechnung) puede traer una dolorosa Nachzahlung (regularización a pagar)",
  "Heated disbelief — loud but not vulgar, extremely common. Fine among partners and friends; in a real fight it reads as 'you've lost your mind'.": "Incredulidad acalorada — alta pero no vulgar, muy común. Vale entre pareja y amigos; en una pelea de verdad suena a 'has perdido la cabeza'.",
  "hol mal = casual imperative; note 'das Licht geht nicht' would mean the lamp itself is broken, not a power cut": "hol mal = imperativo informal; ojo: 'das Licht geht nicht' significaría que la lámpara está rota, no que hay un apagón",
  "Hopeful repair language. 'Hinkriegen' is colloquial and warm — much more natural than 'reparieren'.": "Lenguaje de reparación esperanzado. 'Hinkriegen' es coloquial y cálido — mucho más natural que 'reparieren'.",
  "How Germans sell a friend before you meet them. Note the future: 'den wirst du bestimmt mögen' — present 'den magst du' would claim you already like someone you've never met. 'witzig' is for a person's sense of humour; 'lustig' leans towards situations and things. The demonstratives 'der/den' instead of 'er/ihn' are standard casual speech about people.": "Así venden los alemanes a un amigo antes de que lo conozcas. Fíjate en el futuro: 'den wirst du bestimmt mögen' — el presente 'den magst du' afirmaría que ya te cae bien alguien a quien nunca has visto. 'witzig' se refiere al humor de una persona; 'lustig' tira más hacia situaciones y cosas. Los demostrativos 'der/den' en lugar de 'er/ihn' son habla informal normal sobre personas.",
  "How Meinungsfreiheit shows up in casual talk. Note: this phrase carries political colouring for some listeners — use with awareness.": "Así aparece la Meinungsfreiheit en la charla informal. Aviso: para algunos oyentes esta frase tiene color político — úsala con conciencia.",
  "How you confess a current obsession. 'Auf Dauerschleife' = on endless loop; casual, very common.": "Así se confiesa una obsesión del momento. 'Auf Dauerschleife' = en bucle infinito; informal, muy común.",
  "How you point a friend towards a doctor or a Beratungsstelle without dropping them. A male speaker says 'der Falsche'. Note the colloquial split of 'dafür' into 'da ... für', which is what people actually say.": "Así diriges a un amigo hacia un médico o una Beratungsstelle sin abandonarlo. Un hablante masculino dice 'der Falsche'. Fíjate en la separación coloquial de 'dafür' en 'da ... für' — así habla la gente de verdad.",
  "HUFFY / JOKING between partners and friends — mock silent treatment after you ate the last slice or spoiled the ending. The pout IS the punchline. Said flat and cold in a real fight it turns childish and genuinely wounding, so the grin is not optional.": "ENFURRUÑADO / EN BROMA entre pareja y amigos — ley del hielo fingida después de que te comieras el último trozo o destriparas el final. El mohín ES el remate. Dicho plano y frío en una pelea de verdad se vuelve infantil y realmente hiriente, así que la sonrisa no es opcional.",
  "HURTFUL — the classic 'immer/nie' generalisation that every couples therapist warns about. You'll hear it a lot; recognise it as venting, and avoid saying it yourself: swap 'immer' for 'heute' and it becomes fair.": "HIRIENTE — la clásica generalización con 'immer/nie' contra la que advierte todo terapeuta de pareja. La oirás mucho; reconócela como desahogo y evita decirla tú: cambia 'immer' por 'heute' y se vuelve justa.",
  "Hyperbole among friends about shocking behaviour. Psychopath and Soziopath are heavy armchair diagnoses — clearly banter or clearly serious, nothing in between.": "Hipérbole entre amigos sobre un comportamiento escandaloso. Psychopath y Soziopath son diagnósticos de sofá muy pesados — o claramente broma o claramente en serio, nada intermedio.",
  "idiomatic, informal": "idiomático, informal",
  "Im Alter von 30 = at the age of 30. As an exclamation, Alter! = dude! — very casual.": "Im Alter von 30 = a los 30 años. Como exclamación, Alter! = ¡tío! — muy informal.",
  "in casual speech often shortened to was: Hast du was gehört?": "en el habla informal se acorta a menudo a was: Hast du was gehört?",
  "In Discord contexts everyone says 'der Channel'; the German 'Kanal' survives for YouTube channels, oddly enough. Casual imperative with softening 'mal'.": "En Discord todo el mundo dice 'der Channel'; el alemán 'Kanal' sobrevive, curiosamente, para los canales de YouTube. Imperativo informal con un 'mal' suavizador.",
  "In the moment": "En el momento",
  "Informal": "Informal",
  "Informal — friends only": "Informal — solo entre amigos",
  "Informal — the spoken contraction you'll usually hear": "Informal — la contracción hablada que se oye normalmente",
  "Informal — to strangers or staff say: Sprechen Sie Englisch?": "Informal — a desconocidos o al personal se dice: Sprechen Sie Englisch?",
  "Informal and rude: jemandem den Stinkefinger zeigen.": "Informal y grosero: jemandem den Stinkefinger zeigen.",
  "Informal and uncountable: Nimm dein Zeug mit. It is also the tail of many compounds -- Werkzeug, Fahrzeug, Flugzeug.": "Informal e incontable: Nimm dein Zeug mit. También es la cola de muchos compuestos — Werkzeug, Fahrzeug, Flugzeug.",
  "Informal and warm, mostly southern. 'Grüß Gott' is its formal, Bavarian and Austrian cousin.": "Informal y cálido, sobre todo en el sur. 'Grüß Gott' es su primo formal, bávaro y austriaco.",
  "Informal imperative among friends at a party or in the car. The 'mal' softens the command. Opposite: 'Mach mal leiser!'": "Imperativo informal entre amigos en una fiesta o en el coche. El 'mal' suaviza la orden. Contrario: 'Mach mal leiser!'",
  "Informal imperative of separable 'ablehnen' is 'Lehn ... ab'; after 'wenn', 'kennst' goes to the end.": "El imperativo informal del separable 'ablehnen' es 'Lehn ... ab'; tras 'wenn', 'kennst' va al final.",
  "Informal imperative of separable 'aufheben': 'Heb ... auf'; the full written form is 'Hebe'.": "Imperativo informal del separable 'aufheben': 'Heb ... auf'; la forma escrita completa es 'Hebe'.",
  "informal loan from English; das Okay – the go-ahead": "préstamo informal del inglés; das Okay – el visto bueno",
  "Informal reply — with Sie say: Und Ihnen?": "Respuesta informal — con Sie se dice: Und Ihnen?",
  "Informal term for a friend": "Término informal para un amigo",
  "informal, e.g. eine brenzlige Situation": "informal, p. ej. eine brenzlige Situation",
  "informal; the standard German way to say someone drifted off into conspiracy land": "informal; la forma alemana estándar de decir que alguien se ha ido al mundo de las conspiraciones",
  "Informal. 'dir' adds the idea of wishing for something for yourself and is the usual form here: 'Was wünschst du dir ...?' Formal version: Was wünschen Sie sich zum Geburtstag?": "Informal. 'dir' añade la idea de desear algo para uno mismo y es la forma habitual aquí: 'Was wünschst du dir ...?' Versión formal: Was wünschen Sie sich zum Geburtstag?",
  "Introducing": "Presentarse",
  "Ironic pub humour — twists the serious slogan 'Alkohol ist keine Lösung'. Friends only; know that it IS a joke before deploying it.": "Humor de bar irónico — retuerce el lema serio 'Alkohol ist keine Lösung'. Solo entre amigos; sábete que ES un chiste antes de soltarlo.",
  "Jokey, internet-flavoured pet-parent talk among friends. Self-aware and affectionate – don't use it at the vet's front desk.": "Habla jocosa y con sabor a internet de 'padre de mascota' entre amigos. Autoconsciente y cariñosa — no la uses en el mostrador del veterinario.",
  "JOKING but pointed — half confession, half comment on the length. WhatsApp's speed button is a genuine fixture of German friendships. Note the collocation 'in doppelter Geschwindigkeit' (not 'auf'); casually you'd just say 'auf 2x'. The answer you'll get: 'Dann red ich eben schneller.'": "EN BROMA pero con puntería — mitad confesión, mitad comentario sobre la duración. El botón de velocidad de WhatsApp es un pilar real de las amistades alemanas. Fíjate en la colocación 'in doppelter Geschwindigkeit' (no 'auf'); en tono informal dirías simplemente 'auf 2x'. La respuesta que recibirás: 'Dann red ich eben schneller.'",
  "JOKING-ACCUSING between friends; die blauen Haken (blue ticks) count as evidence. The 'doch' is what makes it teasing rather than cold. Genuinely annoyed, a German would say less, not more: just 'Du hast nicht geantwortet.'": "ACUSACIÓN EN BROMA entre amigos; die blauen Haken (los ticks azules) cuentan como prueba. El 'doch' es lo que lo vuelve pulla y no frialdad. De verdad molesto, un alemán diría menos, no más: solo 'Du hast nicht geantwortet.'",
  "justifying one more — works for cigarettes and beers alike; very casual": "para justificar uno más — vale igual para cigarrillos que para cervezas; muy informal",
  "kicken — casual football. der Bolzplatz — the scuffed pitch every neighbourhood has.": "kicken — fútbol informal. der Bolzplatz — el campillo pelado que tiene cada barrio.",
  "kippen used transitively = to topple/overturn — colloquial force inside legal talk, which is exactly how lawyers speak.": "kippen usado transitivamente = tumbar, anular — fuerza coloquial dentro del lenguaje jurídico, que es exactamente como hablan los abogados.",
  "klamm — damp, and colloquially short of cash. Honest without being dramatic.": "klamm — húmedo, y coloquialmente sin blanca. Honesto sin ser dramático.",
  "klingen — sounding. The honest warning given to every violin household's neighbours.": "klingen — sonar. La advertencia honesta a los vecinos de toda casa con violín.",
  "knapp bei Kasse — tight at the till. The honest sentence that friends answer with einladen.": "knapp bei Kasse — justo de caja. La frase honesta a la que los amigos responden con einladen.",
  "knapp bei Kasse sein = to be short of money; casual register, said among friends and family": "knapp bei Kasse sein = andar corto de dinero; registro informal, entre amigos y familia",
  "Knast = colloquial for jail/prison": "Knast = coloquial para cárcel, trena",
  "Komm doch mal vorbei! — the casual open invitation.": "Komm doch mal vorbei! — la invitación abierta e informal.",
  "kopieren und einfügen is the standard wording, but casual speech happily verbs the loan — 'einfach copy-pasten' — especially among younger people; Strg+C, Strg+V is the shared shorthand.": "kopieren und einfügen es la formulación estándar, pero el habla informal verbaliza encantada el préstamo — 'einfach copy-pasten' — sobre todo entre los jóvenes; Strg+C, Strg+V es la abreviatura compartida.",
  "Krankmeldung (colloquial) is what people say; the official document is the Krankschreibung / AU-Bescheinigung": "Krankmeldung (coloquial) es lo que dice la gente; el documento oficial es la Krankschreibung o AU-Bescheinigung",
  "Ladder level 2, MEDIUM-MILD — like 'damn'. Fine among adults and colleagues you know; avoid in formal or religious settings.": "Nivel 2 de la escala, MEDIO-SUAVE — como 'maldita sea'. Vale entre adultos y con compañeros conocidos; evítalo en contextos formales o religiosos.",
  "Ladder level 3, MEDIUM — the most-heard German swear word, roughly like 'shit' but even more common and slightly less taboo. Fine among friends; avoid with clients, bosses you don't know, or in formal settings.": "Nivel 3 de la escala, MEDIO — la palabrota alemana más oída, más o menos como 'mierda' pero aún más común y algo menos tabú. Vale entre amigos; evítala con clientes, jefes que no conoces o en contextos formales.",
  "Ladder level 4, STRONG — for genuine anger or shock. Friends only; heads will turn if you shout it in public.": "Nivel 4 de la escala, FUERTE — para enfado o susto de verdad. Solo entre amigos; gritado en público, todas las cabezas se giran.",
  "Ladder level 5, STRONG insult — a real attack, never banter-safe with strangers. LEGAL WARNING: calling a stranger 'Arschloch' in public is Beleidigung, a criminal offence in Germany, and courts have fined it at over 1,000 euros.": "Nivel 5 de la escala, insulto FUERTE — un ataque real, nunca vale como broma con desconocidos. AVISO LEGAL: llamar 'Arschloch' a un desconocido en público es Beleidigung, un delito en Alemania, y los tribunales lo han multado con más de 1.000 euros.",
  "Ladder level 6, VERY STRONG — fighting words that can start a physical fight and a criminal complaint. Never safe, not even as banter with most friends. Learn to recognise it, don't use it.": "Nivel 6 de la escala, MUY FUERTE — palabras de pelea que pueden desatar una agresión física y una denuncia penal. Nunca seguro, ni siquiera como broma con la mayoría de los amigos. Aprende a reconocerlo, no lo uses.",
  "lassen + infinitive: you let the hair do the growing. Also the polite warning that you want almost nothing cut.": "lassen + infinitivo: dejas que el pelo crezca. Y también es la advertencia educada de que casi no quieres que corten nada.",
  "Leaving": "Irse",
  "Level 2, medium-mild — like English 'damn'; fine among adults, avoid formal settings": "Nivel 2, medio-suave — como el 'damn' inglés; vale entre adultos, evítalo en contextos formales",
  "Literally 'he doesn't have all his cups in the cupboard'. Teasing between friends, harsh about strangers — dose carefully.": "Literalmente 'no tiene todas las tazas en el armario'. Guasón entre amigos, duro sobre desconocidos — dosifícalo con cuidado.",
  "Literally 'it is not good eating cherries with him' — a warning about someone's temper. Old, odd grammar, still completely current.": "Literalmente 'con él no se comen bien las cerezas' — una advertencia sobre el carácter de alguien. Gramática antigua y rara, todavía plenamente vigente.",
  "Literally 'luck game' — the umbrella and legal term for gambling. Glücksspiel kann süchtig machen is the mandatory warning on every ad.": "Literalmente 'juego de suerte' — el término paraguas y jurídico para el juego de azar. Glücksspiel kann süchtig machen es la advertencia obligatoria en cada anuncio.",
  "Literally 'you can remove that make-up' — a plan dismissed as never going to happen. Blunt but not rude between friends.": "Literalmente 'eso te lo puedes desmaquillar' — un plan descartado como imposible. Directo pero no grosero entre amigos.",
  "Loadout": "Equipamiento",
  "Logisch! is also a casual \"obviously\"": "Logisch! es también un 'obvio' informal",
  "Making a move": "Dar el primer paso",
  "Making plans": "Hacer planes",
  "medium insult — banter-safe among close friends with the right tone": "insulto medio — vale como broma entre amigos cercanos con el tono adecuado",
  "MEDIUM insult — with a grin and the right tone it's banter-safe among close friends; shouted at a stranger (e.g. in traffic) it's an insult that can be reported to the police.": "Insulto MEDIO — con una sonrisa y el tono adecuado vale como broma entre amigos cercanos; gritado a un desconocido (por ejemplo en el tráfico) es un insulto denunciable a la policía.",
  "medium-strong — banter only with thick-skinned close friends": "de fuerza media-alta — solo en broma con amigos cercanos de piel dura",
  "MEDIUM-STRONG — literally 'full fencepost'. Popular in traffic rants and among friends with thick skin; genuinely insulting to anyone else.": "MEDIO-FUERTE — literalmente 'poste de valla entero'. Popular en las broncas de tráfico y entre amigos de piel dura; realmente insultante para cualquier otro.",
  "MEDIUM-STRONG — softer than 'Arschloch' but still a real accusation of being a bad person. Between friends it can signal genuine hurt, not banter.": "MEDIO-FUERTE — más suave que 'Arschloch' pero aún una acusación real de ser mala persona. Entre amigos puede señalar una herida de verdad, no una broma.",
  "Medium, extremely common — genuine outrage or playful disbelief depending on tone. Fine among friends and family.": "Medio, muy común — indignación sincera o incredulidad juguetona según el tono. Vale entre amigos y familia.",
  "Messaging — informal (du); in formal calls: Ich schreibe Ihnen eine Nachricht": "Mensajería — informal (du); en contextos formales: Ich schreibe Ihnen eine Nachricht",
  "Meta": "Meta",
  "MILD-MEDIUM — dismissive ('you're not right in the head') rather than aggressive. Banter-safe among friends.": "SUAVE-MEDIO — despectivo ('no estás bien de la cabeza') más que agresivo. Vale como broma entre amigos.",
  "MILD-MEDIUM — often affectionate among friends and family ('you silly thing'). Still rude to strangers.": "SUAVE-MEDIO — a menudo cariñoso entre amigos y familia ('tontorrón'). Con desconocidos sigue siendo grosero.",
  "mild-medium — often affectionate banter among friends": "suave-medio — a menudo broma cariñosa entre amigos",
  "MILD-MEDIUM, very common in Bavaria and Austria — between friends it's usually affectionate teasing. Banter-safe with friends; rude to strangers.": "SUAVE-MEDIO, muy común en Baviera y Austria — entre amigos suele ser una broma cariñosa. Vale como chanza con amigos; grosero con desconocidos.",
  "mithelfen — pitching in. The morning-after miracle that separates friends from guests.": "mithelfen — echar una mano. El milagro de la mañana siguiente que separa a los amigos de los invitados.",
  "MOCK OUTRAGE after a spoiler — hand on forehead, theatrical. 'versauen' = to ruin/mess up, casual and a shade crude but totally normal. Genuine anger uses the exact same words, so the grin does the sorting.": "INDIGNACIÓN FINGIDA tras un spoiler — mano en la frente, teatral. 'versauen' = arruinar, informal y algo basto, pero de lo más normal. El enfado de verdad usa exactamente las mismas palabras, así que es la sonrisa la que separa.",
  "mocking the classic 'Spiegel-Poser', a fixture of every gym; casual, said behind their back": "burla del clásico 'Spiegel-Poser', fijo en todo gimnasio; informal, dicho a sus espaldas",
  "mocking, informal; the Aluhut is THE German ridicule image for conspiracists": "burlón, informal; el Aluhut es LA imagen alemana de burla hacia los conspiranoicos",
  "mögen + person = plain liking, zero romance implied — safe about colleagues, friends, your partner's brother. Speech usually adds 'gern' ('Ich mag ihn echt gern'), which textbooks call redundant and natives say anyway. Careful: 'Ich mag dich' said TO a date is a soft confession, one rung below 'Ich hab dich lieb'.": "mögen + persona = simpatía llana, cero romance implícito — seguro sobre compañeros, amigos, el hermano de tu pareja. Al hablar se suele añadir 'gern' ('Ich mag ihn echt gern'), que los manuales llaman redundante y los nativos dicen igual. Cuidado: 'Ich mag dich' dicho A una cita es una confesión suave, un peldaño por debajo de 'Ich hab dich lieb'.",
  "nachfragen — following up. The sentence that saves the friendship.": "nachfragen — preguntar de nuevo. La frase que salva la amistad.",
  "neu laden = to reload — neu as an adverb before the verb; einfach shrugs it casual.": "neu laden = recargar — neu como adverbio delante del verbo; einfach le da el tono informal.",
  "Neutral opener that signals something is on your mind; works with friends and family.": "Entrada neutra que avisa de que algo te ronda la cabeza; sirve con amigos y familia.",
  "neutral small talk; works with anyone — casually dropped article is typical": "charla neutra; vale con cualquiera — el artículo omitido sin más es típico",
  "neutral word; among friends it's almost always 'die Kippe'": "palabra neutra; entre amigos casi siempre es 'die Kippe'",
  "Neutral-casual; 'Abi' is what everyone says — the full 'Abitur' sounds formal.": "Neutro-informal; todo el mundo dice 'Abi' — el completo 'Abitur' suena formal.",
  "Neutral-casual; 'kriegen' is the spoken form of 'bekommen'.": "Neutro-informal; 'kriegen' es la forma hablada de 'bekommen'.",
  "Neutral-colloquial; 'zuschlagen' = to throw a punch, to strike.": "Neutro-coloquial; 'zuschlagen' = soltar un golpe, pegar.",
  "NEUTRAL-FORMAL, the first thing you say when someone returns your call — at work it's practically obligatory. 'der Rückruf' is the noun hiding inside 'zurückrufen'; with friends you'd just say 'Danke, dass du zurückrufst.'": "NEUTRO-FORMAL, lo primero que dices cuando alguien te devuelve la llamada — en el trabajo es prácticamente obligatorio. 'der Rückruf' es el sustantivo escondido en 'zurückrufen'; con amigos dirías simplemente 'Danke, dass du zurückrufst.'",
  "Neutral, casual — a no-fuss way to not drink without explaining yourself. No justification expected.": "Neutro, informal — una manera sencilla de no beber sin dar explicaciones. Nadie espera una justificación.",
  "Neutral, casual 'hab'. The standard sequel to Verspätung — deliver it with weary resignation, not anger.": "Neutro, 'hab' informal. La continuación estándar de Verspätung — dilo con resignación cansada, no con enfado.",
  "Neutral, common — disbelief that hovers between amused and appalled. Safe with anyone informal.": "Neutro, habitual — incredulidad a medio camino entre la risa y el espanto. Seguro con cualquiera en registro informal.",
  "Neutral, friendly — the standard joke opener among friends, family and colleagues. 'den' refers to der Witz.": "Neutro, amistoso — la entrada estándar a un chiste entre amigos, familia y colegas. 'den' remite a der Witz.",
  "Neutral, respectful — THE standard phrase for someone in recovery from alcoholism. Not slang, not a euphemism; it conveys respect for the achievement.": "Neutro, respetuoso — LA expresión estándar para alguien en recuperación de un alcoholismo. Ni argot ni eufemismo; transmite respeto por el logro.",
  "Neutral, to friends/family/partner. THE suggestion — a leisurely loop, especially Sunday afternoon.": "Neutro, a amigos, familia o pareja. LA sugerencia — una vuelta tranquila, sobre todo el domingo por la tarde.",
  "Neutral, to whoever planned the route. 'Die Tour' is the casual word for a planned hike.": "Neutro, a quien haya planeado la ruta. 'Die Tour' es la palabra informal para una caminata planificada.",
  "News German: eine Bombe wurde gefunden und entschärft. The colloquial praise needs the definite article — das ist die Bombe = that's brilliant; with eine it is taken literally.": "Alemán de noticiario: eine Bombe wurde gefunden und entschärft. El elogio coloquial exige el artículo definido — das ist die Bombe = eso es genial; con eine se entiende literalmente.",
  "noch kein(e) softens the negation to 'not yet / not by itself' — the standard phrasing of this warning in German academic prose.": "noch kein(e) suaviza la negación a 'todavía no / no por sí solo' — la formulación estándar de esta advertencia en la prosa académica alemana.",
  "Not just 'differently' but inverted — you think the cause and the effect have been swapped. 'andersrum' is the spoken form of 'andersherum', and 'seh's' is 'sehe es'. Direct but not rude among friends and colleagues.": "No solo 'de otra manera' sino al revés — crees que se han intercambiado la causa y el efecto. 'andersrum' es la forma hablada de 'andersherum', y 'seh's' equivale a 'sehe es'. Directo pero no grosero entre amigos y compañeros.",
  "Note the preposition: 'auf den Weihnachtsmarkt' (auf + Akkusativ), not zu or in. From late November this is THE default suggestion for dates, friends and colleagues alike — nobody ever needs a reason.": "Ojo con la preposición: 'auf den Weihnachtsmarkt' (auf + acusativo), no zu ni in. Desde finales de noviembre es LA propuesta por defecto para citas, amigos y compañeros por igual — nadie necesita jamás un motivo.",
  "Noun phrase + und + consequence — a conditional without wenn; landen in = to end up in, informal and vivid.": "Sintagma nominal + und + consecuencia — una condicional sin wenn; landen in = acabar en, informal y muy gráfico.",
  "oder so = or something / or whatever (casual suggestions)": "oder so = o algo así (sugerencias informales)",
  "Officially the elektronische Gesundheitskarte (eGK); colloquially Versichertenkarte or Krankenkassenkarte. You usually have a few weeks to present it retroactively": "Oficialmente la elektronische Gesundheitskarte (eGK); coloquialmente Versichertenkarte o Krankenkassenkarte. Normalmente tienes unas semanas para presentarla después",
  "On Discord, 'der Server' means the community space — the same word as a game server; context decides which. Casual invitation.": "En Discord, 'der Server' se refiere al espacio de la comunidad — la misma palabra que para un servidor de juego; decide el contexto. Invitación informal.",
  "One of the most-used verbs in spoken German. 'Mich nervt an ihm, dass ...' = what annoys me about him is that ... Bare version between friends: 'Du nervst!' = you're being annoying.": "Uno de los verbos más usados del alemán hablado. 'Mich nervt an ihm, dass ...' = lo que me molesta de él es que ... Versión desnuda entre amigos: 'Du nervst!' = estás siendo pesado.",
  "One word does what English needs five for — no body part needed, everyone knows it's the ankle. Keep this for friends; at the doctor's you'd say 'Ich habe mir den Knöchel verstaucht.'": "Una sola palabra hace lo que el inglés necesita cinco para decir — sin nombrar la parte del cuerpo, todos saben que es el tobillo. Guárdalo para los amigos; en el médico dirías 'Ich habe mir den Knöchel verstaucht.'",
  "Only with close friends or your partner — for many Germans, vote choice is genuinely private (Wahlgeheimnis culture). Asking a colleague or acquaintance can land as intrusive.": "Solo con amigos cercanos o con tu pareja — para muchos alemanes el voto es realmente privado (cultura del Wahlgeheimnis). Preguntárselo a un compañero o a un conocido puede sonar intrusivo.",
  "Opinion": "Opinión",
  "Ordering food": "Pedir comida",
  "Peak German summer household knowledge: you close the Rollladen in the morning and keep the heat out all day. 'die Bude' = the place/gaff — casual and affectionate about your own flat, mildly rude about someone else's.": "Sabiduría doméstica veraniega alemana en estado puro: cierras las Rollladen por la mañana y mantienes el calor fuera todo el día. 'die Bude' = la casa, el piso — informal y cariñoso sobre el tuyo, algo grosero sobre el de otro.",
  "personal question — fine among friends or partners, odd with strangers or colleagues; note glauben an + accusative": "pregunta personal — vale entre amigos o en pareja, rara con desconocidos o compañeros; fíjate en glauben an + acusativo",
  "Plans": "Planes",
  "Platform warning before train doors close": "Aviso en el andén antes de que se cierren las puertas del tren",
  "Players say Wishlist even though Steam's German UI says Wunschliste; 'schon ewig' = for ages. Neutral-casual.": "Los jugadores dicen Wishlist aunque la interfaz alemana de Steam ponga Wunschliste; 'schon ewig' = desde hace un siglo. Neutro-informal.",
  "Playful defensiveness, mild — said with mock indignation when friends laugh at your mishap. Casual settings.": "Defensa juguetona, suave — dicho con indignación fingida cuando los amigos se ríen de tu percance. Contextos informales.",
  "pleite — from bankruptcy, used casually. 'gerade' makes it temporary.": "pleite — de la bancarrota, usado informalmente. 'gerade' lo vuelve pasajero.",
  "plural 'Jungs' = guys, lads (colloquial)": "plural 'Jungs' = chicos, tíos (coloquial)",
  "polite check with friends before lighting up; expected around non-smokers": "consulta educada a los amigos antes de encender; se espera si hay no fumadores",
  "polite warning shot before or instead of details; 'heikel' = delicate/tricky": "aviso educado antes de los detalles o en lugar de ellos; 'heikel' = delicado, espinoso",
  "polite-casual at the salon; was = etwas in spoken German": "educado e informal en la peluquería; was = etwas en el alemán hablado",
  "Position callout": "Aviso de posición",
  "Post-betrayal confession to close friends or a therapist. Raw and serious — the 'einfach' carries the helplessness. Vertrauen wants a dative object here: niemandem.": "Confesión tras una traición, a amigos cercanos o a un terapeuta. Cruda y seria — el 'einfach' carga con la impotencia. Vertrauen pide aquí un objeto en dativo: niemandem.",
  "Post-breakup confession to close friends; serious and vulnerable, no banter register.": "Confesión tras una ruptura a los amigos cercanos; seria y vulnerable, nada de tono de broma.",
  "Pronounced letter by letter, pe-em-ess, and said openly to partners and close friends. The pre-emptive 'nimm's nicht persönlich' is what turns it into a heads-up rather than a complaint.": "Se pronuncia letra a letra, pe-eme-ese, y se dice abiertamente a la pareja y a los amigos cercanos. El 'nimm's nicht persönlich' preventivo es lo que lo convierte en un aviso y no en una queja.",
  "Reacting": "Reaccionar",
  "Reassuring": "Tranquilizar",
  "Relationship status": "Estado sentimental",
  "Reporting a problem": "Informar de un problema",
  "Request": "Petición",
  "resigned, informal; standard line among worried friends of a Schwurbler": "resignado, informal; la frase estándar entre amigos preocupados de un Schwurbler",
  "resigned; extremely common among friends and family of someone who's gone down the hole": "resignado; muy habitual entre amigos y familia de alguien que se ha metido en ese pozo",
  "Retail-investor bravado among friends; 'nachkaufen' = to buy more of what you already hold": "bravuconería de inversor particular entre amigos; 'nachkaufen' = comprar más de lo que ya tienes",
  "Rhetorical exasperation about media/politics. Bonding move among friends; the 'mal ehrlich' invites shared sighing.": "Exasperación retórica sobre los medios o la política. Un gesto de complicidad entre amigos; el 'mal ehrlich' invita al suspiro compartido.",
  "Routine": "Rutina",
  "Said to friends — who will name it instantly: that's a red flag ('eine Red Flag' — the English term is standard German dating slang now). Controlling behaviour, not love.": "Dicho a los amigos — que lo nombrarán al instante: eso es una red flag ('eine Red Flag' — el término inglés ya es argot de citas estándar en alemán). Conducta de control, no amor.",
  "Said while handing over the Mitbringsel at the door, informal.": "Se dice al entregar el Mitbringsel en la puerta, informal.",
  "SARCASM — 'danke auch' is never sincere; it's the flat, annoyed 'thanks a bunch'. Jokey between friends, but the irritation underneath is real.": "SARCASMO — 'danke auch' nunca es sincero; es el 'muchas gracias' plano y molesto. Jocoso entre amigos, pero la irritación de fondo es real.",
  "Sarcastic, mild — slightly more pointed than 'Sehr witzig.' Friends and family; signals the joke was at your expense.": "Sarcástico, suave — un pelín más punzante que 'Sehr witzig.' Amigos y familia; señala que el chiste fue a tu costa.",
  "Say this when someone is about to see mutual friends or family. To several listeners, use 'Grüßt'.": "Dilo cuando alguien está a punto de ver a amigos comunes o a la familia. A varios oyentes, usa 'Grüßt'.",
  "Scheduling": "Programar",
  "schlauchen — sapping your energy like a hose. Colloquial and exactly right.": "schlauchen — chuparte la energía como una manguera. Coloquial y exactísimo.",
  "schreiben = to write / spell (informal)": "schreiben = escribir / deletrear (informal)",
  "Seasons": "Estaciones",
  "self-deprecating joke; 'ich schwör' is casual spoken German": "broma a costa de uno mismo; 'ich schwör' es alemán hablado informal",
  "separable: 'Ich probier mal was aus.' Casual speech clips it to 'probieren': 'Ich probier mal ne andere Waffe'": "separable: 'Ich probier mal was aus.' En el habla informal se recorta a 'probieren': 'Ich probier mal ne andere Waffe'",
  "sich befassen mit = to engage with; the je/desto frame around a negation — avoidance measured in growth.": "sich befassen mit = ocuparse de; el armazón je/desto en torno a una negación — la evitación medida en crecimiento.",
  "sich etwas freihalten — keeping a day open. The advance reservation of friendship.": "sich etwas freihalten — dejarse un día libre. La reserva anticipada de la amistad.",
  "sich hinlegen — putting yourself down. 'mal' makes it casual, not dramatic.": "sich hinlegen — echarse a descansar. 'mal' lo vuelve informal, no dramático.",
  "sich kurzschließen = to quickly sync (colloquial workplace); aneinander vorbeiarbeiten is a set idiom.": "sich kurzschließen = coordinarse rápido (coloquial de oficina); aneinander vorbeiarbeiten es una expresión fija.",
  "Slang": "Argot",
  "Slang — the English loan stays English; ein deutsches Bad is a bathroom": "Argot — el préstamo inglés sigue siendo inglés; ein deutsches Bad es un cuarto de baño",
  "Slang (voll = really/very)": "Argot (voll = realmente, muy)",
  "Slang expression of enthusiasm": "Expresión de entusiasmo en argot",
  "Slightly fuller version of the same question. Both are informal; with Sie: 'Was für Musik hören Sie?' — rare, music talk is almost always du-territory.": "Versión algo más completa de la misma pregunta. Ambas son informales; con Sie: 'Was für Musik hören Sie?' — raro, porque hablar de música es casi siempre terreno de du.",
  "Small-talk staple with international friends and colleagues; expect Germans to argue about their own answer.": "Un clásico de la charla con amigos y colegas internacionales; cuenta con que los alemanes discutirán su propia respuesta.",
  "Some platforms add friends through masculine 'der Freundescode'; accusative is 'deinen Freundescode'.": "Algunas plataformas añaden amigos mediante el masculino 'der Freundescode'; en acusativo, 'deinen Freundescode'.",
  "spiegelglatt — mirror-smooth. The radio traffic warning word.": "spiegelglatt — liso como un espejo. La palabra de aviso del parte de tráfico en la radio.",
  "Spoken as a warning: unfinished, buggy, roadmap promises. Used unmodified as an English noun (der Early Access).": "Dicho como advertencia: inacabado, con errores, promesas de hoja de ruta. Se usa sin cambios como sustantivo inglés (der Early Access).",
  "spoken clip of 'Dispositionskredit'; 'im Dispo sein' = to be overdrawn — casual, everyone says it": "recorte hablado de 'Dispositionskredit'; 'im Dispo sein' = estar en números rojos — informal, lo dice todo el mundo",
  "Spoken word order: the demonstrative 'den/der' instead of 'ihn/er' is completely normal about people in casual speech — familiar, not rude. 'in Ordnung sein' = to be a decent sort.": "Orden de palabras del habla: el demostrativo 'den/der' en lugar de 'ihn/er' es de lo más normal sobre personas en registro informal — familiar, no grosero. 'in Ordnung sein' = ser buena gente.",
  "standard match-day question among friends, colleagues, in the Kneipe": "la pregunta estándar en día de partido entre amigos, colegas, en el Kneipe",
  "Standard term in news and casual talk alike; can get heated between generations.": "Término estándar tanto en las noticias como en la charla informal; entre generaciones puede caldearse.",
  "Standard third-person relationship analysis among friends; casual armchair-psychology weight.": "El típico análisis de la relación ajena entre amigos; psicología de sofá en tono informal.",
  "Statistically the most likely reply you'll get in any German city. 'selber' is the colloquial form of 'selbst' and it's what you'll actually hear. Handy in reverse too, when someone asks you.": "Estadísticamente la respuesta más probable en cualquier ciudad alemana. 'selber' es la forma coloquial de 'selbst' y es lo que oirás de verdad. Útil también al revés, cuando te lo preguntan a ti.",
  "Status callout": "Aviso de estado",
  "Straight from the Kiyosaki playbook; drop it in money talks with friends — some will nod, some will roll their eyes": "Directo del repertorio de Kiyosaki; suéltalo en charlas de dinero con amigos — algunos asentirán, otros pondrán los ojos en blanco",
  "Strong accusation — normal among friends, conversation-ending in a debate; die Desinformation is the more clinical term": "Acusación grave — normal entre amigos, en un debate acaba con la conversación; die Desinformation es el término más clínico",
  "Strong agreement": "Acuerdo rotundo",
  "Strong verb with a vowel change: ich stehle, du stiehlst, er stiehlt, gestohlen. The casual everyday word is klauen.": "Verbo fuerte con cambio vocálico: ich stehle, du stiehlst, er stiehlt, gestohlen. La palabra informal de cada día es klauen.",
  "Strong, final dislike — you've given up on this person. Friends-only register: saying it about a colleague inside the office is a political act. Remember: ausstehen has no positive form.": "Antipatía fuerte y definitiva — has dado por perdida a esa persona. Registro solo para amigos: decirlo de un compañero dentro de la oficina es un acto político. Recuerda: ausstehen no tiene forma positiva.",
  "Strong, vulgar — aimed at a person it's aggressive; blurted at bad news it means 'you have got to be kidding'. Among close friends it can be half-joking; never at strangers or at work.": "Fuerte, vulgar — dirigido a una persona es agresivo; soltado ante malas noticias significa 'no me lo puedo creer'. Entre amigos cercanos puede ser medio en broma; nunca con desconocidos ni en el trabajo.",
  "Strong, vulgar — an aggressive order to leave. Sometimes rough banter among very close friends, but hostile to anyone else.": "Fuerte, vulgar — una orden agresiva de largarse. A veces chanza bruta entre amigos muy cercanos, pero hostil para cualquier otro.",
  "stronger and less casual than widerlich finden": "más fuerte y menos informal que widerlich finden",
  "Sunday is legally protected quiet time: no drill, no lawnmower, and in strict houses no washing machine either. 'Das gibt Ärger' = that'll cause trouble — the standard warning formula.": "El domingo es tiempo de silencio protegido por ley: nada de taladro, nada de cortacésped, y en las casas estrictas tampoco lavadora. 'Das gibt Ärger' = eso va a traer problemas — la fórmula de advertencia estándar.",
  "Surprise": "Sorpresa",
  "Sweet, slightly childlike peace offer — usually said with an outstretched hand or open arms. The kindergarten echo ('Vertragt euch!') is exactly what makes it disarming between adults. Partner, family, close friends.": "Oferta de paz dulce y algo infantil — se dice normalmente con la mano tendida o los brazos abiertos. El eco de guardería ('Vertragt euch!') es justo lo que la vuelve desarmante entre adultos. Pareja, familia, amigos cercanos.",
  "Symptom": "Síntoma",
  "talking about quitting with friends or partner": "hablar de dejarlo con amigos o con la pareja",
  "tanken — refuelling. Driving on the warning light is called auf Reserve fahren.": "tanken — repostar. Conducir con el testigo encendido se llama auf Reserve fahren.",
  "Team play": "Juego en equipo",
  "Teasing between partners or friends; 'etwa' adds the playful gotcha tone.": "Broma entre pareja o amigos; 'etwa' añade el tono juguetón de pillarte.",
  "Telling time": "Decir la hora",
  "Texting": "Mensajes",
  "That little 'mal' turns the question into a casual favour. Without it the sentence is still correct, just blunter.": "Ese pequeño 'mal' convierte la pregunta en un favor informal. Sin él la frase sigue siendo correcta, solo más seca.",
  "The -chen ending makes it small and playful. Warm among friends and with children; it would sound odd in an office.": "La terminación -chen lo hace pequeño y juguetón. Cálido entre amigos y con niños; en una oficina sonaría raro.",
  "The 'doch' does the work: it concedes that things went your way and not mine. Spelling: 'recht haben' lowercase is the usual form today — the 1996 reform pushed 'Recht haben', but the 2006 revision allowed both again. Warm between friends — or, with the right sigh, thoroughly grudging.": "El 'doch' hace el trabajo: concede que las cosas salieron a tu favor y no al mío. Ortografía: 'recht haben' en minúscula es hoy la forma habitual — la reforma de 1996 impuso 'Recht haben', pero la revisión de 2006 volvió a permitir ambas. Cálido entre amigos — o, con el suspiro adecuado, del todo a regañadientes.",
  "The 'gerade' matters — asking about the current obsession, not the all-time answer. Casual, du-form.": "El 'gerade' importa — se pregunta por la obsesión actual, no por la respuesta de siempre. Informal, forma de du.",
  "The 'so meine' is the whole trick: it turns specific doubts into a mild, almost casual reservation, which is far more damaging in German conversation than a direct objection.": "El 'so meine' es todo el truco: convierte dudas concretas en una reserva suave, casi de pasada, y eso hace mucho más daño en una conversación alemana que una objeción directa.",
  "The 2026 reflex, said the way 'google it' was said in 2010 — casual, to anyone; note DIE KI (künstliche Intelligenz is feminine).": "El reflejo de 2026, dicho como se decía 'googléalo' en 2010 — informal, a cualquiera; fíjate en DIE KI (künstliche Intelligenz es femenino).",
  "The Angst compounds take no article: Höhenangst, Flugangst, Prüfungsangst (exam nerves). 'total' is the casual spoken intensifier. Said on ladders, bridges and viewing platforms nationwide.": "Los compuestos con Angst van sin artículo: Höhenangst, Flugangst, Prüfungsangst (nervios de examen). 'total' es el intensificador informal del habla. Se dice en escaleras, puentes y miradores de todo el país.",
  "The Anprobe-zu-Hause strategy: order both, keep one, return the other; casual du-register": "La estrategia Anprobe-zu-Hause: pedir los dos, quedarse uno y devolver el otro; registro de du, informal",
  "The apology that reopens a friendship. 'sich melden' = to get in touch; German expects a reason to follow, but the honest 'Ich hab's einfach nicht geschafft' counts as one.": "La disculpa que reabre una amistad. 'sich melden' = dar señales de vida; el alemán espera que siga una razón, pero el honesto 'Ich hab's einfach nicht geschafft' cuenta como tal.",
  "The apology-shaped chase between colleagues on the same level: admitting you're being annoying is exactly what makes it acceptable. 'nerven' = to be annoying. Too casual for your boss — there you'd write 'Ich wollte nochmal daran erinnern.'": "El recordatorio con forma de disculpa entre compañeros del mismo nivel: admitir que estás dando la lata es justo lo que lo hace aceptable. 'nerven' = ser pesado. Demasiado informal para tu jefe — ahí escribirías 'Ich wollte nochmal daran erinnern.'",
  "The barber will ask you this; colloquially you'll also hear 'Wie viel Millimeter an den Seiten?'": "Esto te lo preguntará el barbero; coloquialmente también oirás 'Wie viel Millimeter an den Seiten?'",
  "The belated introduction after two years of nodding in the stairwell. Germans put 'der/die' in front of their own first name in casual speech — 'Ich bin der Tim', 'Ich bin die Sarah' — friendly and very spoken. The 'übrigens' makes it sound spontaneous rather than overdue.": "La presentación tardía tras dos años de saludos con la cabeza en la escalera. En el habla informal los alemanes ponen 'der/die' delante de su propio nombre — 'Ich bin der Tim', 'Ich bin die Sarah' — amistoso y muy hablado. El 'übrigens' hace que suene espontáneo y no atrasado.",
  "The bots are used like first names, no article: Ich hab Claude/ChatGPT gefragt — exactly how you'd report asking a friend; completely normal in casual speech.": "Los bots se usan como nombres de pila, sin artículo: Ich hab Claude/ChatGPT gefragt — exactamente como contarías que le preguntaste a un amigo; de lo más normal en el habla informal.",
  "The casual imperative is 'Misch'; 'die Karten mischen' is the normal phrase for shuffling.": "El imperativo informal es 'Misch'; 'die Karten mischen' es la expresión normal para barajar.",
  "The casual tier. Beste Grüße, Viele Grüße, VG: the ladder descends with familiarity.": "El escalón informal. Beste Grüße, Viele Grüße, VG: la escalera baja con la confianza.",
  "the casual word for Rad fahren": "la palabra informal para Rad fahren",
  "The classic couple question. 'Sich (Dativ) etwas holen' is the casual verb for getting a pet.": "La pregunta clásica de pareja. 'Sich (Dativ) etwas holen' es el verbo informal para tener una mascota.",
  "The classic hypocrite's hedge — announcing that you won't lästern IS the start of lästern, and everyone knows it. Delivered with a grin among friends; the particle 'ja' makes it wink.": "La coartada hipócrita clásica — anunciar que no vas a lästern ES el comienzo del lästern, y todo el mundo lo sabe. Se dice con una sonrisa entre amigos; la partícula 'ja' hace el guiño.",
  "The classic no-fault breakup explanation — sad but blame-free. What people tell friends afterwards.": "La explicación clásica de una ruptura sin culpables — triste pero sin reproches. Lo que se cuenta después a los amigos.",
  "The clean no. Making it a blanket rule ('grundsätzlich') instead of a judgement about this person is what saves the friendship — a stated principle is something Germans will accept almost without argument.": "El no limpio. Convertirlo en norma general ('grundsätzlich') en lugar de en un juicio sobre esa persona es lo que salva la amistad — un principio declarado los alemanes lo aceptan casi sin discutir.",
  "The clean, non-rude disagreement — 'widersprechen' takes the dative (dir, Ihnen). Fine at work and with friends; slipping in 'jetzt mal' makes it friendlier still.": "El desacuerdo limpio y no grosero — 'widersprechen' rige dativo (dir, Ihnen). Vale en el trabajo y con amigos; colar un 'jetzt mal' lo vuelve todavía más amable.",
  "The colloquial breakup phrase: mit jemandem Schluss machen. What people actually say about boyfriends and girlfriends; 'sich trennen' is the more neutral word, standard for long-term or married couples.": "La expresión coloquial de la ruptura: mit jemandem Schluss machen. Es lo que dice la gente de verdad sobre novios y novias; 'sich trennen' es la palabra más neutra, estándar para parejas de largo recorrido o casadas.",
  "The complete form is useful in writing and careful speech. With friends, 'Versteh ich, aber ...' is the usual quick softener before disagreeing.": "La forma completa es útil por escrito y en un habla cuidada. Con amigos, 'Versteh ich, aber ...' es el suavizador rápido habitual antes de discrepar.",
  "THE confidentiality contract of German friendship — said BEFORE the secret, answered with 'Klar!'. 'unter uns' = between us. Breaking it is a real offence.": "EL contrato de confidencialidad de la amistad alemana — se dice ANTES del secreto y se responde 'Klar!'. 'unter uns' = entre nosotros. Romperlo es una falta de verdad.",
  "The daily 6 p.m. question. 'heute Abend' does the work of 'for dinner' — spoken German needs no meal word. Warning: answering 'Mir egal' starts a longer discussion than any menu.": "La pregunta diaria de las seis. 'heute Abend' hace el trabajo de 'para cenar' — el alemán hablado no necesita el nombre de la comida. Aviso: responder 'Mir egal' desata una discusión más larga que cualquier menú.",
  "THE dating-scene diagnosis of the decade; said casually but half-seriously about anyone who won't commit.": "EL diagnóstico de la década en el mundo de las citas; se dice informalmente pero medio en serio de quien no quiere comprometerse.",
  "The default armchair diagnosis for a bad ex — everyday venting between friends. Casual there, but a genuine insult said to someone's face.": "El diagnóstico de sofá por defecto para un mal ex — desahogo cotidiano entre amigos. Ahí informal, pero un insulto de verdad dicho a la cara.",
  "The default Grußformel — never wrong, never exciting. MfG in casual shorthand.": "La Grußformel por defecto — nunca incorrecta, nunca emocionante. En abreviatura informal: MfG.",
  "The diplomatic way to raise noise: blame the building, not the neighbour. Half warning ('so watch out'), half apology ('so sorry about us') — the listener decides which.": "La manera diplomática de sacar el tema del ruido: culpa al edificio, no al vecino. Mitad advertencia ('así que atento'), mitad disculpa ('perdón por nosotros') — el oyente decide cuál.",
  "The dramatic version for partners and close friends — du-form territory, carries real weight": "La versión dramática para pareja y amigos cercanos — terreno del du, con peso de verdad",
  "The embarrassment-avoidance rule. Half of all lost keys are in the other jacket.": "La regla para evitar bochornos. La mitad de las llaves perdidas están en la otra chaqueta.",
  "The everyday refusal — 'Lust haben' = to feel like doing something, with no matching English verb. With an object it takes auf + Akkusativ: 'keine Lust auf Kino'. Among friends this counts as a complete reason.": "La negativa de cada día — 'Lust haben' = tener ganas de algo, sin verbo inglés equivalente. Con objeto se construye con auf + acusativo: 'keine Lust auf Kino'. Entre amigos cuenta como razón completa.",
  "THE everyday spoken word for angry — more common in real life than 'wütend'. 'sauer auf + Akkusativ': 'Ich bin sauer auf dich' = I'm mad at you. Informal but not rude.": "LA palabra hablada de cada día para enfadado — más común en la vida real que 'wütend'. 'sauer auf + acusativo': 'Ich bin sauer auf dich' = estoy enfadado contigo. Informal pero no grosero.",
  "THE everyday way to say it. 'aufs Klo' is casual and completely normal with family, a partner or friends — 'auf die Toilette' is the neutral version for anywhere else. The 'mal' softens it into a passing remark rather than an announcement.": "LA manera cotidiana de decirlo. 'aufs Klo' es informal y de lo más normal en familia, en pareja o con amigos — 'auf die Toilette' es la versión neutra para todo lo demás. El 'mal' lo convierte en un comentario de pasada y no en un anuncio.",
  "The excited announcement to friends and family. 'Einen Antrag machen' is the standard idiom for proposing.": "El anuncio emocionado a amigos y familia. 'Einen Antrag machen' es la expresión estándar para pedir matrimonio.",
  "The eye-roll cliché — every interviewer has heard it a thousand times. Learn it so you can avoid it; among friends it's only said ironically.": "El cliché de poner los ojos en blanco — todo entrevistador lo ha oído mil veces. Apréndelo para evitarlo; entre amigos solo se dice con ironía.",
  "The feud-avoidance move in a shared laundry room: you ask even though you both know the answer, and even though they aren't standing there. Asking first is the entire trick.": "El movimiento anti-guerra en un lavadero compartido: preguntas aunque ambos sepáis la respuesta, y aunque la otra persona ni siquiera esté ahí. Preguntar primero es todo el truco.",
  "The first question every friend asks. Casual, expected, and everyone wants the full story.": "La primera pregunta que hace cualquier amigo. Informal, esperada, y todos quieren la historia entera.",
  "The first question in any debugging session; gucken is casual everyday German — in the south you'd hear schauen.": "La primera pregunta de cualquier sesión de depuración; gucken es alemán cotidiano informal — en el sur oirías schauen.",
  "The fixed idiom, literally 'I don't trust her across the road' — stronger and more colourful than plain 'Ich trau ihr nicht'. Friends-only gossip register, never about a colleague within earshot.": "El modismo fijo, literalmente 'no me fío de ella ni cruzando la calle' — más fuerte y más gráfico que el escueto 'Ich trau ihr nicht'. Registro de cotilleo solo entre amigos, nunca sobre un compañero que pueda oírte.",
  "THE fixed phrase for going independent — works with your boss, your bank and your friends alike. Keep the matching word: 'ich mache mich selbstständig', 'du machst dich selbstständig'.": "LA expresión fija para establecerse por cuenta propia — funciona igual con tu jefe, con tu banco y con tus amigos. Conserva la palabra que la acompaña: 'ich mache mich selbstständig', 'du machst dich selbstständig'.",
  "The flare-up warning. Move it to the side; never pour water on.": "La advertencia por la llamarada. Apártalo a un lado; nunca le eches agua.",
  "The Friday-evening brief. 'mitdenken' = to think along with it. The relative 'wo' instead of 'bei dem' is casual spoken German and completely normal here — the correct version would sound like a job application.": "El resumen del viernes por la tarde. 'mitdenken' = pensar a la vez. El relativo 'wo' en lugar de 'bei dem' es alemán hablado informal y aquí de lo más normal — la versión correcta sonaría a carta de motivación.",
  "The friendly decline of a taste — the 'so' is doing all the softening. For hobbies, genres, food, nights out; never about a person. Bare 'Nicht mein Ding.' is blunter but still fine among friends.": "El rechazo amable de un gusto — el 'so' hace todo el trabajo de suavizar. Para aficiones, géneros, comida, salidas; nunca sobre una persona. El escueto 'Nicht mein Ding.' es más seco pero sigue valiendo entre amigos.",
  "The German friendship accounting system in one line: nobody splits every bill, you just take turns. Naming the last round is what makes the offer stick instead of starting a polite scuffle over the bill.": "El sistema contable de la amistad alemana en una línea: nadie divide cada cuenta, simplemente os vais turnando. Nombrar la ronda anterior es lo que hace que el ofrecimiento aguante en lugar de desatar un forcejeo educado por la cuenta.",
  "The German ID card — der Perso in casual speech.": "El documento de identidad alemán — der Perso en el habla informal.",
  "THE gossip verb: 'über jemanden lästern' (über + Akkusativ) = to talk about someone behind their back. Mildly naughty rather than evil — a good chunk of German friendship maintenance happens while lästern.": "EL verbo del cotilleo: 'über jemanden lästern' (über + acusativo) = hablar de alguien a sus espaldas. Más travieso que malvado — buena parte del mantenimiento de la amistad alemana ocurre mientras se lästern.",
  "THE gym-bro question; casual, between guys who lift": "LA pregunta de gimnasio; informal, entre gente que levanta pesas",
  "The hedge 'eher' is key — Germans rarely self-label without it. Safe self-description among friends.": "El atenuante 'eher' es clave — los alemanes rara vez se etiquetan sin él. Autodescripción segura entre amigos.",
  "The hike itself; casually also 'die Tour'.": "La caminata en sí; informalmente también 'die Tour'.",
  "The honest cost warning. Under a hundred euros, most people simply pay.": "La advertencia honesta sobre el coste. Por debajo de cien euros, la mayoría simplemente paga.",
  "The honest warning, issued once and remembered forever by flatmates.": "La advertencia honesta, dicha una vez y recordada para siempre por los compañeros de piso.",
  "The hopeful announcement after a crisis — 'einen Neuanfang wagen' is the fixed collocation (literally 'dare a new beginning'). Friends will nod supportively and worry privately.": "El anuncio esperanzado tras una crisis — 'einen Neuanfang wagen' es la colocación fija (literalmente 'atreverse a un nuevo comienzo'). Los amigos asentirán con apoyo y se preocuparán en privado.",
  "The hopeful walk-in confession. Sunday lunch and Friday evening genuinely need a booking in Germany; 'geht trotzdem was?' is casual but completely fine to say to staff.": "La confesión esperanzada de quien entra sin reserva. La comida del domingo y el viernes por la noche exigen reserva de verdad en Alemania; 'geht trotzdem was?' es informal pero perfectamente correcto con el personal.",
  "The host's standard warm goodbye at the door, informal.": "La despedida cálida estándar del anfitrión en la puerta, informal.",
  "THE idiom for total incomprehension — casual, universally known. A learner using it always gets a laugh and instant goodwill.": "EL modismo de la incomprensión total — informal, conocido por todos. Cuando lo usa quien está aprendiendo, siempre arranca una risa y simpatía inmediata.",
  "The informal general recommendation question. Add a category or place when it is not already clear from the conversation.": "La pregunta general de recomendación, en registro informal. Añade una categoría o un lugar cuando no queden ya claros por la conversación.",
  "the key de-escalation and warmth line in mixed-belief couples and friendships; sincere register": "la frase clave para bajar la tensión y dar calidez en parejas y amistades de creencias distintas; registro sincero",
  "The late-summer warning. Cover your drink — the wasp finds it anyway.": "La advertencia de finales de verano. Tapa tu bebida — la avispa la encontrará igual.",
  "The lazy option among friends when everyone ate roughly the same — 'durch drei machen' or 'durch drei teilen'. It's a choice, not a necessity: genuinely separate bills are no trouble at all in Germany.": "La opción cómoda entre amigos cuando todos comieron más o menos lo mismo — 'durch drei machen' o 'durch drei teilen'. Es una elección, no una necesidad: las cuentas realmente separadas no dan ningún problema en Alemania.",
  "THE modern smalltalk opener — colleagues, dates, new flatmates. Has largely replaced weather talk. Du-form for anyone you're casual with.": "LA apertura moderna de la charla — compañeros, citas, nuevos compañeros de piso. Ha sustituido en gran medida a hablar del tiempo. Forma de du con cualquiera con quien tengas confianza.",
  "The modern standard framing, used in public health and everyday talk alike. 'der Alkoholiker' is neutral-clinical; 'der Säufer' (drunkard) is the slur to avoid.": "La formulación estándar moderna, usada tanto en salud pública como en la charla cotidiana. 'der Alkoholiker' es neutro-clínico; 'der Säufer' (borrachín) es el insulto que hay que evitar.",
  "the modern word for conspiracy-rambling; informal and very common now": "la palabra moderna para el desvarío conspiranoico; informal y hoy muy habitual",
  "The most common casual check-in — short for Wie geht es?": "La forma informal más común de interesarse — abreviatura de Wie geht es?",
  "The most disarming repair line in German: admits BOTH that they were right and that you went too far. Costs pride, buys peace. Partners and close friends.": "La frase reparadora más desarmante del alemán: admite AMBAS cosas — que la otra persona tenía razón y que tú te pasaste. Cuesta orgullo, compra paz. Pareja y amigos cercanos.",
  "The most famous Zeugnis code line: tried hard, achieved nothing. Also used jokingly among friends: 'Naja, ich war stets bemüht.'": "La frase en clave más famosa del Zeugnis: se esforzó, no consiguió nada. También se usa en broma entre amigos: 'Naja, ich war stets bemüht.'",
  "THE music smalltalk question, du-form. The 'so' makes it casual — literally 'what do you listen to, like?'. Standard on dates and new friendships.": "LA pregunta de charla sobre música, forma de du. El 'so' la vuelve informal — literalmente '¿qué escuchas, así en general?'. Estándar en citas y amistades nuevas.",
  "The normal everyday phrase — 'meine Periode' sounds medical, 'meine Regel' a bit clinical and older. Completely neutral with friends and partners; at work most people say nothing at all.": "La expresión normal de cada día — 'meine Periode' suena médico, 'meine Regel' algo clínico y más anticuado. Del todo neutra con amigos y pareja; en el trabajo la mayoría no dice nada.",
  "The order that avoids regret. Half a percent matters less than one good extra.": "El orden que evita arrepentimientos. Medio punto importa menos que un buen extra.",
  "The other direction. Note the dative: jemandem kündigen. Colloquial 'Ich wurde gekündigt' is widespread but strictly wrong.": "La dirección contraria. Fíjate en el dativo: jemandem kündigen. El coloquial 'Ich wurde gekündigt' está muy extendido pero, en rigor, es incorrecto.",
  "The permission that keeps friendships alive through a separation.": "El permiso que mantiene vivas las amistades a través de una separación.",
  "The phone-only goodbye — literally 'until we hear each other again', where face to face it's 'Auf Wiedersehen'. Saying 'Auf Wiedersehen' down the phone is the classic learner slip that natives clock instantly. Formal register; with friends you end on 'Tschüss!' or 'Ciao!'": "La despedida exclusiva del teléfono — literalmente 'hasta que volvamos a oírnos', mientras que cara a cara se dice 'Auf Wiedersehen'. Decir 'Auf Wiedersehen' por teléfono es el desliz clásico de quien aprende, que los nativos detectan al instante. Registro formal; con amigos se acaba con 'Tschüss!' o 'Ciao!'",
  "The playful threat escalation — 'gleich' (in a second) gives fair warning. 'kitzlig sein' = to be ticklish: 'Bist du kitzlig?'": "La escalada de amenaza juguetona — 'gleich' (en un segundo) da un aviso justo. 'kitzlig sein' = tener cosquillas: 'Bist du kitzlig?'",
  "The polite exit that puts the other person first — you're not ending the call, you're freeing them. Very common with friends and family; German needs no equivalent of the English 'go'.": "La salida educada que pone a la otra persona por delante — no estás terminando la llamada, la estás liberando. Muy común con amigos y familia; el alemán no necesita equivalente del 'go' inglés.",
  "The positive mirror. 'Etwas/nichts/viel von jemandem halten' is THE casual pattern for rating people.": "El espejo positivo. 'Etwas/nichts/viel von jemandem halten' es EL patrón informal para valorar a la gente.",
  "The pre-emptive strike, and the whole trick of money between friends: say it before they have to. After that nobody feels weird about the ten euros.": "El movimiento anticipado, y todo el truco del dinero entre amigos: dilo antes de que tengan que hacerlo ellos. Después de eso nadie se siente raro por diez euros.",
  "The promise that keeps friendships": "La promesa que conserva las amistades",
  "The proud line — drop it casually among friends and watch the questions start.": "La frase orgullosa — suéltala como quien no quiere la cosa entre amigos y mira empezar las preguntas.",
  "The question betrayed partners actually ask their friends. Verzeihen is the deep word — 'entschuldigen' would be absurdly light for infidelity.": "La pregunta que las parejas engañadas les hacen de verdad a sus amigos. Verzeihen es la palabra profunda — 'entschuldigen' sería absurdamente ligero para una infidelidad.",
  "The quiet ending of many friendships, described without accusation.": "El final silencioso de muchas amistades, descrito sin reproches.",
  "The reciprocity ledger of friendship — informal, unwritten, never forgotten.": "El libro de cuentas de la reciprocidad en la amistad — informal, no escrito, nunca olvidado.",
  "The refusal that protects the friendship by naming the rule, not the person.": "La negativa que protege la amistad porque nombra la norma, no a la persona.",
  "The saying as Germans actually quote it in heartbreak conversations. Friends deploy it as a warning against taking someone back; the counter-camp answers 'Menschen können sich ändern'.": "El dicho tal como lo citan de verdad los alemanes en las conversaciones de desamor. Los amigos lo despliegan como advertencia contra volver con alguien; el bando contrario responde 'Menschen können sich ändern'.",
  "The sentence that softens hard truths between friends.": "La frase que suaviza las verdades duras entre amigos.",
  "The sequence that avoids visible edges. Professionals call it 'vorschneiden'.": "La secuencia que evita los bordes visibles. Los profesionales lo llaman 'vorschneiden'.",
  "The set reply when someone asks for you by name. 'der Apparat' is the old word for a telephone set and survives almost nowhere else — nobody calls a phone an Apparat any more, but everyone says 'am Apparat'. Neutral-to-formal; with friends it's just 'Ja, ich bin's.'": "La respuesta fija cuando alguien pregunta por ti por tu nombre. 'der Apparat' es la palabra antigua para un aparato telefónico y no sobrevive casi en ningún otro sitio — ya nadie llama Apparat a un teléfono, pero todos dicen 'am Apparat'. De neutro a formal; con amigos es simplemente 'Ja, ich bin's.'",
  "The slow-burn version: 'langsam' means the patience is running out, not gone. Drop it and you get the sharp 'Jetzt reicht's!', which is a full stop, not a warning.": "La versión de combustión lenta: 'langsam' significa que la paciencia se está agotando, no que se haya agotado. Quítalo y obtienes el cortante 'Jetzt reicht's!', que es un punto final, no una advertencia.",
  "The so makes the question casual — 'what do you do, generally?' The small-talk classic.": "El so vuelve la pregunta informal — '¿a qué te dedicas, en general?' El clásico de la charla.",
  "The softest possible way to say 'that's wrong'. 'draufschauen' keeps it casual; 'prüfen' or 'kontrollieren' make it sound like you're demanding an investigation.": "La manera más suave posible de decir 'eso está mal'. 'draufschauen' lo mantiene informal; 'prüfen' o 'kontrollieren' suenan a que exiges una investigación.",
  "The solemn one — anniversaries, vows, letters. Partner only; too big for casual goodbyes.": "La fórmula solemne — aniversarios, votos, cartas. Solo para la pareja; demasiado grande para despedidas informales.",
  "The spoken du-command is 'Klick'; a more formal warning is 'Klicken Sie nicht auf den Link'.": "La orden hablada de du es 'Klick'; una advertencia más formal sería 'Klicken Sie nicht auf den Link'.",
  "The standard ask on a night out — friendly and low-pressure, works with friends and strangers alike. Fills an obvious gap: the pack covers drinks, the bill and the door queue but never the dancing.": "La petición estándar de una noche de fiesta — amable y sin presión, funciona igual con amigos que con desconocidos. Llena un hueco evidente: el paquete cubre las bebidas, la cuenta y la cola de la entrada, pero nunca el baile.",
  "The standard closing courtesy among friends. Expected, and noticed if forgotten.": "La cortesía de despedida estándar entre amigos. Se espera, y se nota si se olvida.",
  "The standard earworm complaint, informal. Often followed by singing it and infecting everyone else.": "La queja estándar por una canción pegadiza, informal. Suele seguirle cantarla y contagiar a todos los demás.",
  "The standard evening sign-off — always 'ins Bett'. Slangier: 'Ich geh pennen.' Add 'Gute Nacht' and you're free to leave.": "La despedida estándar de la noche — siempre 'ins Bett'. Más de argot: 'Ich geh pennen.' Añade 'Gute Nacht' y ya puedes irte.",
  "The standard go-live announcement to friends and Discord; streamen conjugates like any German verb (gestreamt).": "El aviso estándar de que empiezas a emitir, para amigos y Discord; streamen se conjuga como cualquier verbo alemán (gestreamt).",
  "The standard sigh after any pay-rise or salary talk; casual, universal": "El suspiro estándar tras cualquier subida o charla de sueldo; informal, universal",
  "the standard verb; coden is its casual twin": "el verbo estándar; coden es su gemelo informal",
  "The standard warm reply you WILL hear — 'echt' makes it casual and sincere. Just say 'Danke!', don't argue.": "La respuesta cálida estándar que SEGURO oirás — 'echt' la vuelve informal y sincera. Di simplemente 'Danke!', no discutas.",
  "the standard way to disclose a serious rift; neutral register, works with friends and colleagues alike": "la manera estándar de revelar una ruptura seria; registro neutro, sirve con amigos y con colegas por igual",
  "The standard way to promise a return invitation at the door, informal.": "La forma estándar de prometer la invitación de vuelta en la puerta, informal.",
  "the standard word; casually 'die Muckibude' or just 'das Gym'": "la palabra estándar; informalmente 'die Muckibude' o simplemente 'das Gym'",
  "The stylist asks this at the end; reinmachen is casual spoken German": "Esto lo pregunta el peluquero al final; reinmachen es alemán hablado informal",
  "The universal German 'huh?' — totally normal between partners and friends, rude to strangers or your boss (there: 'Wie bitte?'). Learn to hear it too: it signals confusion, not hostility.": "El '¿eh?' alemán universal — de lo más normal entre pareja y amigos, grosero con desconocidos o con tu jefe (ahí: 'Wie bitte?'). Aprende también a oírlo: señala confusión, no hostilidad.",
  "The universal gossip opener among friends and colleagues — it announces juicy news the way a drumroll does. With content: 'Hast du schon gehört, dass ...?'. Gen Z also announces it with the English loan 'Drama': 'Es gab mal wieder Drama.'": "La apertura universal del cotilleo entre amigos y compañeros — anuncia una noticia jugosa como un redoble de tambor. Con contenido: 'Hast du schon gehört, dass ...?'. La generación Z también lo anuncia con el préstamo inglés 'Drama': 'Es gab mal wieder Drama.'",
  "the universal hotline complaint — said to the agent who finally picks up, or vented to friends afterwards; 'hängen' is the fixed verb": "la queja universal de las líneas de atención — dicha al agente que por fin descuelga, o desahogada después con los amigos; 'hängen' es el verbo fijo",
  "the universal leg-day complaint; casual": "la queja universal del día de piernas; informal",
  "The vague 'die' (them = politicians) is characteristic of casual political talk. Can spark generational debate, so read the room.": "El vago 'die' (ellos = los políticos) es típico de la charla política informal. Puede desatar un debate generacional, así que lee el ambiente.",
  "THE verdict on a celebrity gone arrogant — literally 'lifted off' the ground; also works for ex-friends who got successful": "EL veredicto sobre un famoso que se ha vuelto arrogante — literalmente 'despegado' del suelo; sirve también para ex amigos a los que les ha ido bien",
  "The warning against illegal puppy trade. Cheap, sick, and it funds more of it.": "La advertencia contra el tráfico ilegal de cachorros. Barato, enfermo, y financia más de lo mismo.",
  "The warning light before something honest: 'Versteh mich nicht falsch, aber ...'. Exactly as in English, whatever follows the 'aber' is the real message.": "La luz de aviso antes de algo sincero: 'Versteh mich nicht falsch, aber ...'. Exactamente como en inglés, lo que sigue al 'aber' es el mensaje de verdad.",
  "The written warning from an employer or lawyer — one step before consequences.": "La amonestación escrita del empleador o de un abogado — un paso antes de las consecuencias.",
  "This impersonal passive is a playful way to announce an unavoidable routine without repeatedly saying 'you'.": "Esta pasiva impersonal es una forma juguetona de anunciar una rutina inevitable sin repetir 'tú'.",
  "Time comment": "Comentario sobre la hora",
  "To friends or your partner right after trying a new word. Invites a gentle correction.": "A amigos o a tu pareja justo después de probar una palabra nueva. Invita a una corrección amable.",
  "TOP of the ladder, MOST SEVERE — ends friendships, starts fights, and counts as criminal Beleidigung. Understand it instantly when you hear it; there is almost no situation where you should say it.": "CIMA de la escala, LO MÁS GRAVE — acaba con amistades, provoca peleas y cuenta como Beleidigung punible. Entiéndelo al instante cuando lo oigas; casi no hay situación en la que debas decirlo.",
  "TRAP: 'die Fabrik' is a factory, not fabric. Fabric is 'der Stoff' — which itself also means 'material' and, colloquially, 'drugs'. German enjoys this.": "TRAMPA: 'die Fabrik' es una fábrica, no una tela. Tela es 'der Stoff' — que además significa 'material' y, coloquialmente, 'droga'. El alemán se divierte con esto.",
  "Two words that stop a small hand. 'Vorsicht' works alone as a warning.": "Dos palabras que detienen una mano pequeña. 'Vorsicht' funciona solo como advertencia.",
  "Typical reply": "Respuesta típica",
  "über die Runden kommen = make ends meet; idiomatic, signals real financial strain without drama; friends and family": "über die Runden kommen = llegar a fin de mes; idiomático, señala una tensión económica real sin dramatismo; amigos y familia",
  "überweisen + dative person — sending money person-to-person. How friends settle up in Germany.": "überweisen + persona en dativo — enviar dinero de persona a persona. Así se saldan cuentas entre amigos en Alemania.",
  "um einen Gefallen bitten — the formal opening of informal help. Germans appreciate the framing.": "um einen Gefallen bitten — la apertura formal de una ayuda informal. A los alemanes les gusta ese encuadre.",
  "umrühren separable; anbrennen = burn onto the pot bottom — different from verbrennen (burn up); casual kitchen command, du-form.": "umrühren es separable; anbrennen = pegarse al fondo de la olla — distinto de verbrennen (quemarse del todo); orden de cocina informal, forma de du.",
  "Understatement instead of criticism: negating an enthusiastic word ('der Hammer' = amazing, colloquial) is the polite German way of saying something was bad. The 'jetzt' is a softening filler, nothing to do with time. Informal — fine about a film or a restaurant, not about someone's cooking to their face.": "Atenuación en lugar de crítica: negar una palabra entusiasta ('der Hammer' = genial, coloquial) es la manera educada que tienen los alemanes de decir que algo estuvo mal. El 'jetzt' es un relleno suavizador, nada que ver con el tiempo. Informal — vale sobre una película o un restaurante, no sobre la cocina de alguien en su cara.",
  "Unlocks": "Desbloqueos",
  "Urgent": "Urgente",
  "Urgent warning": "Advertencia urgente",
  "Verb-first inversion ('ist das ...!') is how German does 'this is SO ...' — works with any adjective: 'Ist das kalt!'. 'Boah' is the everyday spoken wow: perfect with friends and family, a shade too casual at a formal dinner, where 'Ist das lecker!' on its own does the job.": "La inversión con el verbo delante ('ist das ...!') es la manera alemana de decir 'esto es TAN ...' — funciona con cualquier adjetivo: 'Ist das kalt!'. 'Boah' es el guau hablado de cada día: perfecto con amigos y familia, un punto demasiado informal en una cena formal, donde 'Ist das lecker!' por sí solo basta.",
  "verschreien — jinxing by saying. The warning shouted across German offices daily.": "verschreien — gafarlo por decirlo en voz alta. La advertencia que se grita a diario en las oficinas alemanas.",
  "verschwitzen — sweating an appointment away: forgetting it entirely. Casual, honest, forgivable once.": "verschwitzen — sudar una cita hasta olvidarla del todo. Informal, honesto, perdonable una vez.",
  "versterben = formal register: obituaries, doctors, official letters. Using it in casual speech sounds distant; using sterben in an obituary sounds blunt.": "versterben = registro formal: esquelas, médicos, cartas oficiales. En el habla informal suena distante; sterben en una esquela suena brusco.",
  "verstoßen gegen + Akkusativ; mit etwas rechnen müssen is the standard warning of consequences.": "verstoßen gegen + acusativo; mit etwas rechnen müssen es la advertencia estándar de consecuencias.",
  "Very casual slang for friends": "Argot muy informal para los amigos",
  "very casual, friends only; 'Muckibude' (muscle shack) is jokey-affectionate gym slang — 'Fitnessstudio' is the neutral word for it": "muy informal, solo entre amigos; 'Muckibude' (la caseta de los músculos) es argot de gimnasio jocoso y cariñoso — 'Fitnessstudio' es la palabra neutra",
  "very casual, said just before a penalty; 'der' instead of 'er' is typical fan speech": "muy informal, dicho justo antes de un penalti; 'der' en lugar de 'er' es habla típica de aficionados",
  "Very casual: 'ne' = 'eine', 'probier mal' softens it. With friends, not in writing.": "Muy informal: 'ne' = 'eine', 'probier mal' lo suaviza. Con amigos, no por escrito.",
  "Very colloquial and rough. Here 'kein Schwanz' means nobody, not a body part. It can sound crude or dated, so it is more useful to recognise than copy.": "Muy coloquial y áspero. Aquí 'kein Schwanz' significa nadie, no una parte del cuerpo. Puede sonar burdo o anticuado, así que conviene más reconocerlo que copiarlo.",
  "Very colloquial gripe — 'etwas auf die Reihe kriegen' = to get one's act together. Everyday frustration, not extreme.": "Queja muy coloquial — 'etwas auf die Reihe kriegen' = espabilar, poner algo en orden. Frustración cotidiana, nada extremo.",
  "Very common (informal alternative to 'Die Rechnung bitte')": "Muy común (alternativa informal a 'Die Rechnung bitte')",
  "Very common casual slang": "Argot informal muy común",
  "Very common colloquial verb for losing your temper": "Verbo coloquial muy común para perder los nervios",
  "Very common colloquial; about losing your temper, not going crazy.": "Muy común en registro coloquial; va de perder los estribos, no de volverse loco.",
  "Very common in conversation and informal writing; the standard, register-neutral alternative is 'Das ergibt Sinn'.": "Muy común en la conversación y en la escritura informal; la alternativa estándar, neutra de registro, es 'Das ergibt Sinn'.",
  "Very common leisure activity": "Actividad de ocio muy común",
  "Very common, casual — Bock = desire/appetite": "Muy común, informal — Bock = ganas",
  "Very common, casual — literally 'that's sausage to me'": "Muy común, informal — literalmente 'eso me es salchicha'",
  "Very common, direct — friends or real annoyance": "Muy común, directo — entre amigos o con enfado de verdad",
  "Very rude — slightly less aggressive than 'Halt die Fresse' but still hostile. Rough banter possible among close friends only.": "Muy grosero — algo menos agresivo que 'Halt die Fresse' pero igual de hostil. Como chanza bruta solo es posible entre amigos cercanos.",
  "Very rude and aggressive — 'Fresse' is a vulgar word for face/mouth. Among very close friends occasionally joking; to anyone else it invites escalation.": "Muy grosero y agresivo — 'Fresse' es una palabra vulgar para la cara o la boca. Entre amigos muy cercanos, a veces en broma; con cualquier otro invita a la escalada.",
  "vorbeischauen — looking past: the casual visit. 'auf einen Kaffee' — the unit of neighbourliness.": "vorbeischauen — pasarse un momento: la visita informal. 'auf einen Kaffee' — la unidad de medida del buen vecindario.",
  "Vorsicht + statement — the standard kitchen warning shape.": "Vorsicht + enunciado — la forma estándar del aviso de cocina.",
  "Vulgar and confrontational. It challenges what someone has done and can start an argument, so do not use it as a casual question.": "Vulgar y confrontativo. Cuestiona lo que alguien ha hecho y puede desatar una discusión, así que no lo uses como pregunta informal.",
  "VULGAR but not aggressive — the honest shocked reaction between friends, and much warmer than a polite murmur when the news is genuinely bad. Never at work or with your partner's parents; the clean versions are 'Ach du Schreck!' or 'Oh nein!'": "VULGAR pero no agresivo — la reacción de shock honesta entre amigos, y mucho más cálida que un murmullo educado cuando la noticia es realmente mala. Nunca en el trabajo ni con los padres de tu pareja; las versiones limpias son 'Ach du Schreck!' u 'Oh nein!'",
  "Vulgar metaphor for pointless competitive showing off, often between men. Avoid it in formal or professional conversation.": "Metáfora vulgar para el postureo competitivo sin sentido, a menudo entre hombres. Evítala en conversaciones formales o profesionales.",
  "Vulgar-casual: Willst du mich verarschen? = are you kidding me?": "Vulgar e informal: Willst du mich verarschen? = ¿me estás tomando el pelo?",
  "Vulgar-ish (from Arsch = arse), moderately strong — disbelief or being wound up. Friends and close colleagues only; not to your boss or strangers.": "Más bien vulgar (de Arsch, culo), moderadamente fuerte — incredulidad o sensación de que te están vacilando. Solo amigos y compañeros de confianza; no con tu jefe ni con desconocidos.",
  "Vulgar-ish (from Arsch = arse). Fine among friends, avoid with strangers or at work.": "Más bien vulgar (de Arsch, culo). Vale entre amigos, evítalo con desconocidos o en el trabajo.",
  "VULGAR, and deliberately so — this is the anti-platitude. 'schönreden' = to talk something up, to make it sound better than it is; refusing to do it is a form of respect. Between friends this lands far better than 'Alles wird gut.'": "VULGAR, y a propósito — esta es la anti-frase hecha. 'schönreden' = adornar algo, hacer que suene mejor de lo que es; negarse a hacerlo es una forma de respeto. Entre amigos esto cala mucho mejor que 'Alles wird gut.'",
  "Warm but LIGHT: for friends, family, siblings — or very early dating. It is NOT the deep-moment line for a partner; swapping it in for 'Ich liebe dich' can even feel like a downgrade. (French does the same trick: 'je t'aime beaucoup' is weaker than 'je t'aime'.)": "Cálido pero LIGERO: para amigos, familia, hermanos — o el principio de una relación. NO es la frase del gran momento con la pareja; cambiarla por 'Ich liebe dich' puede sentirse incluso como un retroceso. (El francés hace el mismo truco: 'je t'aime beaucoup' es más débil que 'je t'aime'.)",
  "Warm casual goodbye — informal (du), friends only": "Despedida cálida e informal — informal (du), solo entre amigos",
  "warm compliment for partner or close friends; stronger than 'gut'": "cumplido cálido para la pareja o amigos cercanos; más fuerte que 'gut'",
  "Warm compliment, safe in any casual context.": "Cumplido cálido, seguro en cualquier contexto informal.",
  "Warm door greeting to friends (ihr). One person: 'Komm rein!'; formal: 'Kommen Sie rein!'": "Saludo cálido en la puerta para amigos (ihr). Una persona: 'Komm rein!'; formal: 'Kommen Sie rein!'",
  "Warm du-form for friends and family. Softer and more personal than the formal Beileid formulas.": "Forma cálida de du para amigos y familia. Más suave y personal que las fórmulas formales de pésame.",
  "Warm encouragement — comparative + 'als du denkst'. (French shown to a woman; to a man: 'plus courageux'.) Register warning for the opposite: calling someone 'feige' (cowardly) is a genuine insult in German, never banter.": "Ánimo cálido — comparativo + 'als du denkst'. (La versión francesa va dirigida a una mujer; a un hombre: 'plus courageux'.) Aviso de registro para lo contrario: llamar 'feige' (cobarde) a alguien es un insulto de verdad en alemán, nunca una broma.",
  "Warm encouragement from friends — 'dranbleiben' = stick with it. Also what hosts say before a break: 'Bleibt dran!' / formal 'Bleiben Sie dran!'": "Ánimo cálido de los amigos — 'dranbleiben' = seguir con ello. También es lo que dicen los presentadores antes de una pausa: 'Bleibt dran!' / formal 'Bleiben Sie dran!'",
  "Warm goodbye — informal (du), friends only": "Despedida cálida — informal (du), solo entre amigos",
  "Warm team-spirit reassurance after a rough patch — 'hinkriegen' (colloquial: to manage/fix) plus 'wir' says the relationship is bigger than the fight. Constructive, hopeful, partner or close friends.": "Tranquilización cálida en clave de equipo tras una mala racha — 'hinkriegen' (coloquial: arreglar, conseguir) más 'wir' dice que la relación es más grande que la pelea. Constructivo, esperanzado, para la pareja o amigos cercanos.",
  "Warm toast among friends, couples, teams celebrating something together. Follows or replaces 'Prost'.": "Brindis cálido entre amigos, parejas o equipos que celebran algo juntos. Sigue a 'Prost' o lo sustituye.",
  "Warm, casual encouragement before a challenge. 'You've got this' is the most natural English equivalent.": "Ánimo cálido e informal antes de un reto. El equivalente inglés más natural es 'You've got this'.",
  "Warning": "Advertencia",
  "WARNING — this is the wrong move mid-rant and lands as dismissive, exactly like English 'calm down'. Learn it to recognise it; if you want to defuse, use 'Das würde mich genauso fertigmachen' first.": "ADVERTENCIA — en mitad de una perorata es el movimiento equivocado y suena a desprecio, exactamente como el 'calm down' inglés. Apréndelo para reconocerlo; si quieres desactivar, di primero 'Das würde mich genauso fertigmachen'.",
  "Warning the neighbours BEFORE the noise is what stops the complaint ever happening — said at the door or on a note in the stairwell. 'sorry schon mal im Voraus' is the light, half-joking apology-in-advance formula.": "Avisar a los vecinos ANTES del ruido es lo que evita que la queja llegue a existir — dicho en la puerta o en una nota en la escalera. 'sorry schon mal im Voraus' es la fórmula ligera y medio en broma de disculpa anticipada.",
  "Weather": "El tiempo",
  "What you ask the neighbours during an outage; weg sein = to be gone (very common colloquial)": "Lo que preguntas a los vecinos durante un apagón; weg sein = haberse ido (muy común en coloquial)",
  "What your investment earns; 'Rendite abwerfen' = to yield a return, colloquially also 'Rendite machen'": "Lo que gana tu inversión; 'Rendite abwerfen' = dar rendimiento, coloquialmente también 'Rendite machen'",
  "Written German too": "También en alemán escrito",
  "You always 'hört sich' a Sprachnachricht 'an' — never just 'hören'. die Sprachnachricht is a genuine fault line between friends, and declaring you don't listen to them is practically a personality statement. The reproach from the other side: 'Deine Sprachnachricht war sieben Minuten lang.'": "Un Sprachnachricht siempre se lo 'escucha uno' ('sich anhören') — nunca simplemente 'hören'. die Sprachnachricht es una auténtica línea de fractura entre amigos, y declarar que no los escuchas es prácticamente una declaración de personalidad. El reproche del otro lado: 'Deine Sprachnachricht war sieben Minuten lang.'",
  "youth slang from 'suchten' (die Sucht = addiction): hat durchgesuchtet; 'binge-watchen' also works": "argot juvenil de 'suchten' (die Sucht = adicción): hat durchgesuchtet; 'binge-watchen' también vale",
  "youth slang intensifier/negative: 'Mein Ping ist übel' = my ping is terrible. Can also intensify positively: 'übel gut'": "intensificador/negativo del argot juvenil: 'Mein Ping ist übel' = mi ping es horrible. También puede intensificar en positivo: 'übel gut'",
  "Youth/casual slang, mild — genuine or mocking congratulation depending on tone. Friends and younger colleagues; sounds odd from/to older strangers.": "Argot juvenil e informal, suave — felicitación sincera o burlona según el tono. Amigos y compañeros más jóvenes; suena raro viniendo de o dirigido a desconocidos mayores.",
  "zu lebenslanger Haft verurteilt = sentenced to life imprisonment; lebenslanges Lernen = lifelong learning. The parallel adjective lebenslaenglich is the usual word in court reporting and can stand on its own: er bekam lebenslaenglich.": "zu lebenslanger Haft verurteilt = condenado a cadena perpetua; lebenslanges Lernen = aprendizaje a lo largo de toda la vida. El adjetivo paralelo lebenslaenglich es la palabra habitual en las crónicas judiciales y puede ir solo: er bekam lebenslaenglich.",
  "zunächst and bislang bracket the timeline; es das geblieben — das stands for harmlos.": "zunächst y bislang enmarcan la cronología; es das geblieben — das sustituye a harmlos.",
  "zurückzahlen — paying back. The clause that keeps the friendship intact.": "zurückzahlen — devolver el dinero. La cláusula que deja la amistad intacta.",
};
